(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c32"]=[{"id":"00012320","register_sub_id":"101","register_pk":"531644","name":"歓盛寺山門","kana":"かんせいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市二塚1316","lat":36.70496389,"lng":137.002875,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口4.7m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"16-139","desc":"東西棟の切妻造桟瓦葺、三間一戸薬医門で、境内正面に建つ。組物は実肘木付三斗、格天井を張り、軒は一軒繁垂木とする。妻飾の虹梁大瓶束笈形付、中備蟇股、冠木廻り等を精緻な彫刻で飾る。瑞龍寺の脇門を移築したとも伝わり、風格ある寺観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012320"},{"id":"00012319","register_sub_id":"101","register_pk":"531643","name":"歓盛寺離座敷","kana":"かんせいじはなれざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県高岡市二塚1316","lat":36.70515278,"lng":137.00240278,"geo_status":"db","era":"明治39年","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"16-138","desc":"尼僧学林の講師控所として建てられた。総二階建、東西棟の切妻造桟瓦葺で、本堂背面下手に接続する。上下階にそれぞれ八畳二室を置き、奥の部屋はともに座敷飾の床を備える。質素ながら丁寧なつくりで、最初期の曹洞宗尼僧教育の様子を伝える貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012319"},{"id":"00012318","register_sub_id":"101","register_pk":"531642","name":"歓盛寺本堂","kana":"かんせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県高岡市二塚1316","lat":36.70503333,"lng":137.00253611,"geo_status":"db","era":"江戸中期／明治18年・同39年・平成13年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積308㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"16-137","desc":"庄川左岸の田園地帯にあり、東面して建つ。入母屋造桟瓦葺、内部は八間取方丈形式で、前面に幅一間の広縁を通し、中央南寄りに向拝、背面に開山堂を張出す。側廻りは舟肘木。全体に簡明なつくりで、当地における江戸中期の曹洞宗末寺本堂の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012318"},{"id":"00000203","register_sub_id":"101","register_pk":"101193","name":"大楽寺庫裏","kana":"だいらくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県射水市立町2-9","lat":36.78037222,"lng":137.0879726,"geo_status":"db","era":"明治2","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造2階建，瓦葺，建築面積399㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"16 － 0013","desc":"切妻造、妻入で、数寄屋風の大広間、梁をみせた民家風の部屋等をもつ大規模な庫裏。棟札から明治２年９月の大火直後の建築と知られる。古くからの大伽藍を偲ばせる建物であり、小学校の仮校舎に使用されたとも伝える等、その存在が広く知られた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000203"},{"id":"00000202","register_sub_id":"101","register_pk":"101192","name":"大楽寺本堂","kana":"だいらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県射水市立町2-9","lat":36.78031887,"lng":137.08823176,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積263㎡","structure_material":"土蔵造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"16 － 0012","desc":"桁行７間、梁間１１間と大規模な土蔵造の本堂。屋根は切妻造、桟瓦葺になる。平面は浄土宗本堂の伝統的な様式を踏襲しており、奥行きの深い構成になる。正面の向拝は明治２２年の改築で、獅子頭はじめ柱や虹梁を漆喰塗とする精巧な構えとなり見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000202"},{"id":"00012321","register_sub_id":"101","register_pk":"531645","name":"白山宮鞘堂","kana":"はくさんぐうさやどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"富山県","address":"富山県南砺市上梨字家平713他","lat":36.41125,"lng":136.930525,"geo_status":"db","era":"宝暦10年(1760)／大正10年増築、昭和55年移築","year":1760,"year_source":"db","year_min":1760,"year_max":1760,"year_label":null,"structure":"木造平屋建、茅葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"16-140","desc":"五箇山の上梨地区にある白山宮本殿の鞘堂。入母屋造茅葺妻入、軸部は角柱に絵様肘木を載せ、軒はせがい造とし、正面を虹梁と蟇股で飾る。内部は土間の内陣に本殿を安置し、外陣は板敷で格天井に天井絵を描く。豪雪地帯における信仰形態を反映した宗教施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012321"},{"id":"00011669","register_sub_id":"101","register_pk":"210685","name":"養照寺本堂","kana":"ようしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県滑川市領家町551他","lat":36.762329,"lng":137.335636,"geo_status":"db","era":"大正5年頃／平成22年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積452㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0125","desc":"滑川旧市街の西端に建つ。本堂は入母屋造桟瓦葺、桁行五間、梁間六間、向拝三間の規模で、正面及び両側面前半に切目縁を巡らす。向拝以外は全て円柱で、外陣を一室として広くとり、各柱間に虹梁を架け装飾豊かな内部空間とする。滑川の歴史を伝える真宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011669"},{"id":"00003408","register_sub_id":"101","register_pk":"104398","name":"尾山神社東神門","kana":"おやまじんじゃひがししんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市尾山町11-1","lat":36.565441,"lng":136.656158,"geo_status":"db","era":"江戸後期／明治3・昭和38移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0070","desc":"もと金沢城二ノ丸唐門と伝えられる。卯辰山招魂社神門として移されていたものを昭和３８年現在地に移築。１間１戸の向唐門で，屋根は桟瓦葺。主柱は円柱，控柱は角柱で，両開き桟唐戸をたて，頭貫上は蟇股と波彫刻，桁上は大瓶束と雲竜彫刻をあしらう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003408"},{"id":"00003962","register_sub_id":"101","register_pk":"104952","name":"金沢神社拝殿","kana":"かなざわじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市兼六町1-3","lat":36.56050133,"lng":136.66285031,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0092","desc":"本殿の北前方に建つ。入母屋造，桟瓦葺，妻入で，正側面に刎高欄付切目縁，正面に向拝を付ける。軒は三斗組，一軒半繁垂木，妻は虹梁豕叉首とする。内部は主体部を格天井，本殿側は両下屋根の釣殿形式とし，釣殿部分に高欄付の反り橋を設けるなど特徴をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003962"},{"id":"00003961","register_sub_id":"101","register_pk":"104951","name":"金沢神社本殿（旧明倫堂鎮守）","kana":"かなざわじんじゃほんでん（きゅうめいりんどうちんじゅ）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市兼六町1-3","lat":36.56043459,"lng":136.6629181,"geo_status":"db","era":"寛政6","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0091","desc":"はじめ藩校の鎮守として建築された。大型の流造社殿で，身舎円柱上に連三斗，妻は虹梁大瓶束で，虹梁で繋ぐ向拝は水引虹梁，連三斗を備える。間口の広い平面で，身舎正面にも虹梁型頭貫を通し中備蟇股を置き，胡麻殻決りの幣軸を付けて特徴ある構えにつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003961"},{"id":"00001377","register_sub_id":"101","register_pk":"102367","name":"時習庵土蔵（旧実性院土蔵）","kana":"じしゅうあんどぞう（きゅうじっしょういんどぞう）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県加賀市大聖寺神明町20","lat":36.30416089,"lng":136.30675435,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"17 － 0038","desc":"主屋の後方に位置し，背後の山際に建つ２階建ての土蔵。平成９年に現在地に移築の際，腐食していた１階壁体部分はコンクリートに改めている。もとは加賀藩の枝藩大聖寺藩主前田家の菩提寺である実性院にあったもので，天明年間の建築と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001377"},{"id":"00008445","register_sub_id":"101","register_pk":"134841","name":"聖興寺北土蔵","kana":"しょうこうじきたどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1","lat":36.52319965,"lng":136.56521147,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0216","desc":"南蔵の北側、裏玄関を挟んで建つ。南北棟で、切妻造桟瓦葺の置屋根とする。桁行三・七メートル梁間四・一メートルの土蔵造二階建。内部は竪板張で、一、二階とも一室。外壁は漆喰仕上げで、腰を黒漆喰、通り側は腰石貼とし、重厚な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008445"},{"id":"00008440","register_sub_id":"101","register_pk":"134836","name":"聖興寺客殿","kana":"しょうこうじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市西新町23-3他","lat":36.5232646,"lng":136.56485427,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦及び銅板葺、建築面積421㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0211","desc":"大きな唐破風造の玄関を構える大式台を南正面に配し、その北奥に南北二室からなる仏間、その東北に十二畳半を二室南北に並べ、その東西に土縁などを設ける。金の壁紙、黒塗の格天井を張り、漆塗と螺鈿細工の欄間を飾るなど、華美な意匠になる接客空間。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008440"},{"id":"00008443","register_sub_id":"101","register_pk":"134839","name":"聖興寺庫裏","kana":"しょうこうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1","lat":36.52313471,"lng":136.56501055,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積245㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0214","desc":"客殿大式台の東南に西面して建つ。木造二階建、切妻造桟瓦葺。西面に大きく妻を見せ、庇を付設し、玄関や中玄関を開ける。妻面の庇より上方は、上半部を束や貫、舟肘木等で飾り、下半部は下見板張とし、格子付の大きい窓を穿つ。近代的な庫裏の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008443"},{"id":"00008442","register_sub_id":"101","register_pk":"134838","name":"聖興寺座敷","kana":"しょうこうじざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1","lat":36.52324024,"lng":136.56506331,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0213","desc":"茶室と客殿の間の中庭南方に位置する。木造二階建、寄棟造桟瓦葺。一階は前後二列に各三室を配し、西・南・東面に廊下を通し、北面に土縁を設ける。二階も同様に間仕切り、南北に縁を付設する。主要室にトコや棚を設ける和風建築で、接客や居室として使われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008442"},{"id":"00008447","register_sub_id":"101","register_pk":"134843","name":"聖興寺山門","kana":"しょうこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県白山市中町56-1","lat":36.52288913,"lng":136.56456811,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0218","desc":"切妻造本瓦葺の四脚門。出組とし、妻側は中備に蟇股、平側は中央に出組、その間に蟇股を置く。さらに妻は持ち出した虹梁上に笈形付大瓶束をたてるなど密度の濃い軒まわりとする。本柱間の龍彫物や、木鼻や扉まわりの彫刻など、高い装飾性を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008447"},{"id":"00008446","register_sub_id":"101","register_pk":"134842","name":"聖興寺鐘楼","kana":"しょうこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県白山市中町56-1","lat":36.52292161,"lng":136.56449504,"geo_status":"db","era":"江戸中期／昭和51年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、面積10㎡","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0217","desc":"本堂の南方に位置し、戸室石を積み上げた高い基壇上に建つ。入母屋造桟瓦葺の方一間吹放ち鐘楼。粽付の円柱を四方転びにたて、貫や台輪で固め、三斗組を置く。中備は木鼻付平三斗。一軒疎垂木で、格天井を張る。安定した外観をもつ、瀟洒な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008446"},{"id":"00006715","register_sub_id":"101","register_pk":"107698","name":"聖興寺草風庵","kana":"しょうこうじそうふうあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県白山市中町56-1","lat":36.52293589,"lng":136.56430135,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積61㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"17 － 0167","desc":"千代尼堂の南側に東面して建つ。南北棟の入母屋造に、東西棟の入母屋造屋根を付ける凸型の構成を取る。正面中央の突出する部分が広間８畳で、北に茶室４畳、背面から南側に水屋等、正面に土庇を設ける。穏やかな意匠でまとめられた、開放的な草庵風茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006715"},{"id":"00008441","register_sub_id":"101","register_pk":"134837","name":"聖興寺茶室","kana":"しょうこうじちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1他","lat":36.52334781,"lng":136.5652135,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0212","desc":"客殿の東方、中庭を挟んだ位置に建つ。入母屋造桟瓦葺で、寥々庵や翠光軒、暢音堂と称する茶室や座敷を中心に水屋や土縁が配され、東北隅に待合や雪隠を付設する。寥々庵は二畳台目で、磨丸太のトコ柱や竹の框が用いられる。品格のある近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008441"},{"id":"00006714","register_sub_id":"101","register_pk":"107697","name":"聖興寺千代尼堂","kana":"しょうこうじちよにどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県白山市中町56-1","lat":36.52301904,"lng":136.56429881,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積14㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"17 － 0166","desc":"通りに南面する境内の西寄りに東面して建ち、北側に千代尼塚がある。千代尼１５０回忌に記念事業で造られた宝形造茅葺（銅板仮葺）の堂宇。方１間半規模で、背面に仏壇を付ける。天井は化粧垂木を放射状に配し、側面には丸窓を穿つ。数寄屋風仏堂の佳品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006714"},{"id":"00008439","register_sub_id":"101","register_pk":"134835","name":"聖興寺本堂","kana":"しょうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県白山市西新町23-3","lat":36.52320168,"lng":136.56461276,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積577㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0210","desc":"境内中央後方に南面して建つ。桁行二一メートル梁間二二メートル、入母屋造本瓦葺で、正面に一間向拝を付ける。外陣や柵内、内陣などからなる典型的な真宗本堂平面になる。総円柱で、側まわりを二手先斗栱詰組とするなど、風格ある外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008439"},{"id":"00008444","register_sub_id":"101","register_pk":"134840","name":"聖興寺南土蔵","kana":"しょうこうじみなみどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1","lat":36.52311847,"lng":136.56519726,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0215","desc":"庫裏の東方、境内の東端に位置する。南北棟で、切妻造桟瓦葺の置屋根とする。桁行九・一メートル梁間四・三メートルの土蔵造二階建。内部や妻面は漆喰仕上げ。通り側の東面は中塗仕上げとし、鳥居型に一、二階の窓を囲い、街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008444"},{"id":"00006827","register_sub_id":"101","register_pk":"107809","name":"總持寺祖院香積台","kana":"そうじじそいんこうしゃくだい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県輪島市門前町門前壱2-1他","lat":37.286171,"lng":136.769745,"geo_status":"db","era":"昭和29頃","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積584㎡、廊下付","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"17 － 0172","desc":"仏殿の西に所在する２階建の庫裏。切妻造妻入桟瓦葺で、下屋庇をまわす。内部は多くの居室や大台所を間仕切り、北正面から東面の下屋と東面の廊下が回廊の一部をなす。正面は中央間口を２間とし、その両脇や２階に花頭風窓に格子を設け、開放的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006827"},{"id":"00006831","register_sub_id":"101","register_pk":"107813","name":"總持寺祖院禅悦廊","kana":"そうじじそいんぜんえつろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県輪島市門前町門前壱2-1他","lat":37.28642535,"lng":136.76988121,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"17 － 0176","desc":"山門と香積台を繋ぐ、南北３３ｍの廊下。両下造桟瓦葺で、大祖堂正面を一段切り上げる。伽藍正面側の西面は花頭風の窓を穿ち、格子を設け、腰板壁、小壁漆喰仕上げとし、東面は花頭を略す。床土間で、化粧屋根裏天井。大祖堂正面の威風ある構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006831"},{"id":"00006830","register_sub_id":"101","register_pk":"107812","name":"總持寺祖院白山井戸","kana":"そうじじそいんはくさんいど","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県輪島市門前町門前壱2-1他","lat":37.28647442,"lng":136.76994155,"geo_status":"db","era":"明治45頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、面積5.3㎡","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"17 － 0175","desc":"回廊内、大祖堂正面の西方に位置する。井桁組の井戸に、方１間吹放ち宝形造桟瓦葺の井戸屋を設ける。柱間各２．３ｍで、方柱を頭貫と台輪で固め、三斗組とし、中備に蟇股を入れる。一軒扇垂木で、格天井を張る。重厚な建造物群の中、軽やかな佇まいになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006830"},{"id":"00009266","register_sub_id":"101","register_pk":"194059","name":"宝円寺庫裏","kana":"ほうえんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市宝町358","lat":36.5597853,"lng":136.67011098,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積385㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0243","desc":"本堂東側に建ち、木造二階建、建築面積三八五平方メートル、切妻造桟瓦葺で、本堂寄りに玄関を構える。北面庭側に客間や方丈の間を配し南半は台所などとし、二階は廊下の両側に座敷などを並べる。伝統的平面の一階と広い接客施設の二階を併せ持つ大型の庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009266"},{"id":"00009267","register_sub_id":"101","register_pk":"194060","name":"宝円寺山門及び築地塀","kana":"ほうえんじさんもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市宝町358","lat":36.55934407,"lng":136.67038547,"geo_status":"db","era":"明治32年頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"山門 木造、瓦葺、間口2.8m 築地塀 木造、瓦葺、総延長8.4m","structure_material":"山門 木造","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0244","desc":"境内入口に建つ山門と左右の塀である。山門は大型の一間薬医門、切妻造桟瓦葺で、男梁上の三斗で軒桁を受け、冠木上には龍を象った蟇股を飾る。築地塀は精緻な石積基礎上に建ち、両端を前方に出した配置とする。禅院の結界に相応しい厳格な構えをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009267"},{"id":"00009265","register_sub_id":"101","register_pk":"194058","name":"宝円寺本堂","kana":"ほうえんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市宝町358","lat":36.55966038,"lng":136.6698314,"geo_status":"db","era":"明治5年頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積666㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0242","desc":"境内奥に南東面して建つ。桁行二四・八メートル梁間一八・一メートル、入母屋造桟瓦葺で、正面に軒唐破風付の玄関を構え、背面に開山堂を張出す。堂内は内陣と大間を中心に四列八室を配し、縁を廻らせる。標準的な曹洞宗本堂平面をもつ藩主菩提寺の大型本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009265"},{"id":"00005273","register_sub_id":"101","register_pk":"106261","name":"本泉寺手水舎","kana":"ほんせんじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市二俣町子8","lat":36.55833969,"lng":136.76501804,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造、瓦葺、面積5.7㎡","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"17 － 0146","desc":"本堂前方南東寄に建つ木造桟瓦葺の手水舎。断面六角形の柱３本を内転びに立て，アーチ状の梁を渡して丸桁を支える。屋根棟頂部には帽子状の石を据える。大工石崎清左衛門の手になり，明治初期の新しい建築様式への取り組みを表す独特な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005273"},{"id":"00016661","register_sub_id":"101","register_pk":"579145","name":"龍門寺本堂","kana":"りゅうもんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和後","pref":"石川県","address":"石川県七尾市小島町リ15","lat":37.04881,"lng":136.953249,"geo_status":"db","era":"江戸前期／昭和29年改修","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積346㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"17 - 0323","desc":"市街地西方の山中に位置する曹洞宗寺院の本堂。境内中央に南面して建つ、寄棟造平入桟瓦葺で正面西寄りに向唐破風造の向拝を付す。平面は八間取で正面に土間と広縁を通した典型的な方丈形式の本堂。内陣正面に円柱を立て、虹梁や拳鼻の絵様に古式を残す仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016661"},{"id":"00005272","register_sub_id":"101","register_pk":"106260","name":"若草教会（旧日本基督教団金沢教会）礼拝堂","kana":"わかくさきょうかい（きゅうにほんきりすときょうだんかなざわきょうかい）れいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市若草町13-44","lat":36.54472476,"lng":136.65965604,"geo_status":"db","era":"明治24／昭和30移築","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積172㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"17 － 0145","desc":"礼拝堂，祈祷室，和室をＬ字に配する木造平屋建。和室部のみ２階建とし，屋根は急勾配の切妻造，桟瓦葺とする。プロテスタントらしい装飾を排除した内部空間は，天井を張らずに吹き抜けとし，挟み梁とタイ・バーを組合わせた軽快な小屋組を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005272"},{"id":"00000042","register_sub_id":"101","register_pk":"101032","name":"小浜聖ルカ教会","kana":"おばませいるかきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市千種2-14-3-1","lat":35.50181897,"lng":135.74765567,"geo_status":"db","era":"明治30／昭和6改造","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"煉瓦造・木造2階建、瓦葺、建築面積144㎡","structure_material":"煉瓦造・木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"18 － 0001","desc":"明治30年に建設された煉瓦造の教会堂を昭和６年に改造し，煉瓦造の１階部に木造の礼拝堂が２階にのる形とした建物。改造時の設計はバーガミニー，施工は奈良の大木吉太郎である。両者は聖公会の教会を多く手がけたが，その作風をよく示した一例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000042"},{"id":"00006711","register_sub_id":"101","register_pk":"107694","name":"願念寺本堂","kana":"がんねんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県福井市石新保町18字下屋敷割35","lat":36.14818766,"lng":136.10842192,"geo_status":"db","era":"文化3／大正7増築","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積434㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0057","desc":"通り北側の敷地西端に東面して建つ７間堂。１間向拝を付ける入母屋造で、越前赤桟瓦で葺く。柱上二手先組物を置き、軒は二軒繁垂木。内部は浄土真宗の特徴的な平面になり、外陣の彩色画や矢来内の龍の墨画、内陣前の彫刻など華やかな装飾が施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006711"},{"id":"00007486","register_sub_id":"101","register_pk":"108468","name":"西光寺表門","kana":"さいこうじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県鯖江市杉本町31字向垣内42-1","lat":35.98246869,"lng":136.17004313,"geo_status":"db","era":"江戸前期／江戸中期移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、瓦葺、間口3.1m","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0078","desc":"七曲りに西面する一間薬医門。本柱上に冠木を渡し、男梁を架け、その上に木鼻付三斗を組み、格天井を張る。軒は二軒繁垂木、妻は虹梁大瓶束で笈形を付ける。屋根は切妻造桟瓦葺。間口に対して成の高い門で、木鼻や絵様など近世初頭に遡る意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007486"},{"id":"00008451","register_sub_id":"101","register_pk":"134847","name":"聖徳太子堂","kana":"しょうとくたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県越前市平和町58","lat":35.89957554,"lng":136.1627955,"geo_status":"db","era":"嘉永元年（1848）／明治16年改修","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0086","desc":"旧武生市の市街地に位置する。正面一間側面二間、正・側面に組高欄付の切目縁をまわし、正面に一間向拝、背面に仏壇を付設。宝形造桟瓦葺で、笏谷石の相輪を飾る。円柱で三斗組、一軒半繁垂木。内部は一室とし、格天井を張る。地域で護持される堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008451"},{"id":"00013377","register_sub_id":"101","register_pk":"368555","name":"陽願寺客殿","kana":"ようがんじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市本町154","lat":35.900025,"lng":136.16398611,"geo_status":"db","era":"昭和17年頃","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0207","desc":"洋館の西に接続する南北棟で二階建の入母屋造。桁行中央に階段室を設け、二階南の一〇畳主座敷に、床、棚、書院を設け、南に縁を付す。階段から北は上下階とも六畳二室で、二階は数寄屋風座敷、一階北室は内仏の間とする。寺院内の私的空間の有り様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013377"},{"id":"00013373","register_sub_id":"101","register_pk":"368460","name":"陽願寺庫裏","kana":"ようがんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.89998056,"lng":136.16455278,"geo_status":"db","era":"明治前期／昭和30年代増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積292㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0203","desc":"本堂北に建つ切妻造の東西棟で、東正面の妻壁を大虹梁と海老虹梁で飾る。東の玄関は上部に重厚な小屋組を現す。北の台所は土間に床板を張り、中央の板敷は小屋裏を居室とする。南の式台玄関を対面所から移築するなど、一部改造があるが近世以来の様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013373"},{"id":"00013375","register_sub_id":"101","register_pk":"368462","name":"陽願寺御殿","kana":"ようがんじごてん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.9,"lng":136.16417222,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0205","desc":"対面所の西に続く東西棟である。西の座敷と東の次の間は各一〇畳で、座敷の西面に大床を設け、南に畳敷の広縁を通し、落縁と土縁が付く。座敷北の御座の間は奥の六畳を上段に造り、床、棚、書院を設ける。本山門主の接遇を想定した上質な空間を実現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013375"},{"id":"00013380","register_sub_id":"101","register_pk":"368466","name":"陽願寺鐘楼","kana":"ようがんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.89960556,"lng":136.16488333,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造、瓦葺、面積13㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0210","desc":"境内東辺中央に開く山門南側の南北棟で入母屋造。反りのある切石積基壇に建ち、礎盤上に円柱を立てる。虹梁形内法貫は木鼻を獅子とする。頭貫と台輪は彫刻で飾る。組物は出組詰組で、軒は二軒扇垂木とする。禅宗様を基調とした手の込んだ造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013380"},{"id":"00013374","register_sub_id":"101","register_pk":"368461","name":"陽願寺対面所","kana":"ようがんじたいめんしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.89996389,"lng":136.16435278,"geo_status":"db","era":"明治前期／明治44年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積182㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0204","desc":"庫裏の西に続く東西棟。東から広間二〇畳と使者の間一六畳で、対面所一六畳は西面に床と棚を飾る。使者の間と対面所の南は一間幅の畳敷広縁とする。欄間は竹の節である。対面所の西背後の松の間は六畳の小座敷で控の間とする。高い格式を備えた接遇施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013374"},{"id":"00013379","register_sub_id":"101","register_pk":"368465","name":"陽願寺土蔵","kana":"ようがんじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.90013889,"lng":136.16402778,"geo_status":"db","era":"明治30年頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0209","desc":"境内の北西隅に建つ東西棟である。東妻に瓦葺の下屋を付し南半に戸口を設け、北半に漬物小屋を造る。外壁は白漆喰塗に簓子下見張とし、妻壁も塗込めて母屋の形を見せる。小屋組は緩い曲がりの梁に束立で棟木と母屋を受ける。境内背後の景観を構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013379"},{"id":"00013378","register_sub_id":"101","register_pk":"368464","name":"陽願寺納骨堂","kana":"ようがんじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市本町154","lat":35.900025,"lng":136.16484722,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造平屋地下1階建、瓦葺、建築面積21㎡","structure_material":"鉄筋コンクリート造平屋地下1階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0208","desc":"境内の北東隅に建つ宝形造で相輪を戴く。洗出しの基壇をもち、南正面扉口を門形の枠で飾り、両側面は出窓状に壁面を張り出し縦長窓を開く。背面下屋の仏壇両脇から基壇内の納骨室に到る。正側面の高窓から、柔らかく外光を取込むなどの造形を試みている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013378"},{"id":"00013372","register_sub_id":"101","register_pk":"368459","name":"陽願寺本堂","kana":"ようがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.899725,"lng":136.16434444,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積617㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0202","desc":"武生中心市街の真宗寺院で、境内中央に東面して建つ寄棟造の大型本堂である。外陣には広縁と落縁を廻らすが、両側面の広縁奥寄りを堂内化して外陣を拡張する。内外陣境は金箔と彩色で飾る。北余間に鞘の間を取り込んで御簾の間とするなど、高い寺格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013372"},{"id":"00013376","register_sub_id":"101","register_pk":"368463","name":"陽願寺洋館","kana":"ようがんじようかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県越前市本町154","lat":35.89996944,"lng":136.16403889,"geo_status":"db","era":"昭和9年頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0206","desc":"御殿の南面落縁から西に続く東西棟で寄棟造とする。中央の応接室は、南面を台形平面のベイウインドウとし、庭への扉口を設ける。西は書斎で両室とも漆喰塗天井に中心飾りを付す。北に片廊下を通し、御殿との間は便所とする。落ち着いた意匠の応接空間である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013376"},{"id":"00000209","register_sub_id":"101","register_pk":"101199","name":"市川教会","kana":"いちかわきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県西八代郡市川三郷町市川大門907","lat":35.56280619,"lng":138.49989896,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積91㎡","structure_material":"木造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"19 － 0011","desc":"木造平屋建、桟瓦葺の簡素な建物で、天然石の高基礎上に建つ。内部は一室で、正面に半円形の祭壇を設け聖餐台を置く。袴越屋根及び切妻とする玄関妻壁の意匠が特徴的で、漆喰仕上げとする独特の外観は、「今昔通り」と呼ぶ道筋の中心的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000209"},{"id":"00014803","register_sub_id":"101","register_pk":"519061","name":"旧松亭稲荷社","kana":"きゅうしょうていいなりしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲府市中央三丁目263-1他","lat":35.66136667,"lng":138.57482778,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積0.1㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0174","desc":"敷地北西に位置し、切石積基壇に建つ一間社流造の屋敷神。組物は平三斗、軒は一軒繁垂木とし、屋根は鉄板葺で棟は成の高い箱棟風とする。妻飾は虹梁大瓶束。三方に縁を廻らし、正面に木階を付す。懸魚に透彫りの彫刻を付し、敷地北西の景観をつくる稲荷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014803"},{"id":"00016373","register_sub_id":"101","register_pk":"536440","name":"昌福寺大玄関及び小玄関","kana":"しょうふくじおおげんかんおよびしょうげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55866944,"lng":138.46401667,"geo_status":"db","era":"安政4年（1857）／明治5年改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0189","desc":"本堂と庫裏の間で東向きに構える大玄関と、北側の庫裏に接続する小玄関。大玄関は入母屋造妻入桟瓦葺で前一間を吹放ちの式台とし、虹梁に菊花など流麗な彫刻を飾る。小玄関は両下造の廊下状でかつては前面に出入口があった。規模雄大で格式あるつくりの玄関。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016373"},{"id":"00016378","register_sub_id":"101","register_pk":"536445","name":"昌福寺旧七面堂","kana":"しょうふくじきゅうしちめんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55833056,"lng":138.46388889,"geo_status":"db","era":"天保6年（1835）／平成24年改修","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"土蔵造及び木造平屋建、瓦葺、建築面積27㎡","structure_material":"土蔵造及び木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0194","desc":"本堂南側に東面して建ち、かつて七面大明神を祀った。土蔵造入母屋造妻入桟瓦葺の前面に、切妻造妻入の拝所を設ける。主体部は軒裏まで塗込め、腰に水切を廻し、南北面に小窓を開く。内部は格天井で格間に墨絵や川柳を飾る。当地の七面信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016378"},{"id":"00016372","register_sub_id":"101","register_pk":"536439","name":"昌福寺庫裏","kana":"しょうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55882222,"lng":138.46409722,"geo_status":"db","era":"安政4年（1857）／平成24年改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0188","desc":"本堂の北側に大玄関及び小玄関を介し、東面して建つ庫裏。正面切妻造、背面入母屋造で妻入桟瓦葺とし、内部は土間と広間の上部に豪壮な梁組を現す。正面は軸部を化粧で見せ、上部の虹梁大瓶束、両脇の海老虹梁、特異な形式の火灯窓など装飾性も豊かな庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016372"},{"id":"00016379","register_sub_id":"101","register_pk":"536446","name":"昌福寺山門","kana":"しょうふくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55847778,"lng":138.46445833,"geo_status":"db","era":"寛政2年（1790）／平成27年改修","year":1790,"year_source":"db","year_min":1790,"year_max":1790,"year_label":null,"structure":"木造、瓦葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0195","desc":"本堂正面の境内入口で東面する高麗門。切妻造桟瓦葺で左右に段違屋根の袖塀を設ける。門は本柱を太い楣で固め、柱上の拳鼻付大斗実肘木で棟木を受け、男梁端の実肘木で桁を受ける。木鼻や肘木など随所に華やかな絵様を施す。古刹の表構えをつくる大型の山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016379"},{"id":"00016374","register_sub_id":"101","register_pk":"536441","name":"昌福寺書院","kana":"しょうふくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.558875,"lng":138.46384444,"geo_status":"db","era":"安政5年（1858）／平成24年改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0190","desc":"庫裏の西後方に南北棟で建つ書院。入母屋造桟瓦葺で妻飾を雲紋の蟇股や笈形で飾る。座敷は三室を一列に並べて南東面に広縁と濡縁を廻らした開放的なつくり。南端室は西面に間口二間の大床を構え、北端室に床、棚、書院を設えるなど上質なつくりの書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016374"},{"id":"00016377","register_sub_id":"101","register_pk":"536444","name":"昌福寺鐘楼堂","kana":"しょうふくじしょうろうどう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55833333,"lng":138.46420556,"geo_status":"db","era":"安永7年（1778）","year":1778,"year_source":"db","year_min":1778,"year_max":1778,"year_label":null,"structure":"木造2階建、瓦葺、建築面積9.4㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0193","desc":"本堂に至る参道の南側に東面し、大振りの自然石積基壇上に建つ鐘楼。方一間、袴腰付、入母屋造妻入桟瓦葺。高欄付の縁を波紋の持送で支え、上層組物は出組、中備は蟇股とし板支輪に地紋彫を施す。軒は二軒繁垂木。持送など賑やかで細部意匠も凝った鐘楼堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016377"},{"id":"00016371","register_sub_id":"101","register_pk":"536438","name":"昌福寺本堂","kana":"しょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55849167,"lng":138.46391667,"geo_status":"db","era":"元文6年（1741）／明治6年改修","year":1741,"year_source":"db","year_min":1741,"year_max":1741,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積317㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0187","desc":"富士川右岸の境内に東面して建つ日蓮宗寺院本堂。桁行約二〇メートル、入母屋造桟瓦葺、正面向拝付。前面に吹放ちの外陣を通し、六室を配す。堂内中央は内陣と内々陣で、両室は格天井中央を折上げ、格間に彩画を飾り荘厳する。下山大工の力量を示す大型本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016371"},{"id":"00016376","register_sub_id":"101","register_pk":"536443","name":"昌福寺虫切加持堂","kana":"しょうふくじむしきりかじどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55870278,"lng":138.46377778,"geo_status":"db","era":"文化9年（1812）／昭和前期改修","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"土蔵造及び木造平屋建、瓦葺、建築面積60㎡、渡廊下付","structure_material":"土蔵造及び木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0192","desc":"本堂北西に東面して建ち、夜泣や癇癪封じの祈祷をする仏堂。宝形造の前面に入母屋造妻入で軒唐破風付の拝所を接続し、桟瓦葺とする。主体部は土蔵造で腰に七宝風紋様を表し正面に掛子塗土戸を開き、内部格天井に菊花を描く。虫切加持の中核となる特異な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016376"},{"id":"00016375","register_sub_id":"101","register_pk":"536442","name":"昌福寺渡廊下","kana":"しょうふくじわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55876389,"lng":138.46394167,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積8.8㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0191","desc":"庫裏南西隅から書院南東隅に架かる廊下。平行四辺形平面で桁行四間梁間一間、両下造桟瓦葺、床面を反橋状とするが、屋根と軒を直線につくる。柱を桁行の貫で固め、梁を架けて桁を受ける。両側面の手摺は束を千鳥に配る。書院前面の庭空間に風情を添える廊下。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016375"},{"id":"00013991","register_sub_id":"101","register_pk":"508251","name":"冨士山元祠","kana":"ふじさんげんし","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県富士吉田市上吉田字浅間下1-1","lat":35.47303333,"lng":138.79406111,"geo_status":"db","era":"明治9年","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"19 - 0163","desc":"北口本宮冨士浅間神社に隣設。北面し、切妻造金属板葺の正面に唐破風向拝、東西に下屋、南に神殿を付す。正面に縁を通し内部北列は踏込床を囲んで板敷、南列は畳敷三室とし中央奥に正面三間の神殿を配す。土足で祈祷を受ける富士講の形態を残す神殿兼拝所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013991"},{"id":"00011300","register_sub_id":"101","register_pk":"209137","name":"御岳公会堂（旧金櫻神社参籠所）","kana":"みたけこうかいどう（きゅうかなざくらじんじゃさんろうじょ）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市御岳町字上村2368-1","lat":35.767867,"lng":138.556438,"geo_status":"db","era":"昭和10頃／昭和54改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積125㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"19－0084","desc":"金櫻神社境内にあった参籠所を移築し、地区の公会堂としたもの。木造平屋建、鉄板葺であるが、移築前は檜皮葺であったと伝え、小屋組や主要部材は旧状をよく残す。京呂組の架構で内部に柱を建てない大空間など、参籠所としての特色を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011300"},{"id":"00013390","register_sub_id":"101","register_pk":"368475","name":"身延山久遠寺莚師堂","kana":"みのぶさんくおんじえんしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4226","lat":35.38408611,"lng":138.4285,"geo_status":"db","era":"明治9年／平成3年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0153","desc":"中心伽藍北側上方に東面して建つ。桁行四間梁間正面一間背面二間、入母屋造妻入で正面に向拝を付す。内部は前後に二分し、内陣に石造五輪塔を祀る。側柱上の絵様肘木で桁を受ける。内外とも簡素な意匠としつつ扇と天女の蟇股などで向拝回りの装飾性を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013390"},{"id":"00013391","register_sub_id":"101","register_pk":"368476","name":"身延山久遠寺奥之院思親閣鐘堂","kana":"みのぶさんくおんじおくのいんししんかくしょうどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4222","lat":35.39718889,"lng":138.41723611,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、銅板葺、面積13㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0154","desc":"身延山頂に所在する思親閣の鐘堂で、方一間、入母屋造瓦棒銅板葺。内転びの四本丸柱を虹梁形内法貫と頭貫で固め、各面の虹梁形内法貫上に大瓶束を立てる。組物は出組詰組で、内部は出三斗で鏡天井を受ける。軸部堅牢で軒の出も深く、安定感ある姿形の鐘撞堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013391"},{"id":"00012350","register_sub_id":"101","register_pk":"531674","name":"身延山久遠寺甘露門及び門番所","kana":"みのぶさんくおんじかんろもんおよびもんばんしょ","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38058333,"lng":138.42608333,"geo_status":"db","era":"明治元年／昭和16年移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"甘露門 木造、瓦葺、間口4.5m、左右袖塀及び東方潜り付 門番所 木造、瓦葺、建築面積12㎡","structure_material":"甘露門 木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-126","desc":"本坊域南面に建つ。甘露門は切妻造本瓦葺の高麗門で、左右に袖塀と潜りを付す。本柱上の大斗実肘木で直接棟木を受け、貫や腕木の先端を木鼻風につくる。門番所は入母屋造本瓦葺、門背面東側に接続する。規模も雄大で風格ある表構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012350"},{"id":"00012346","register_sub_id":"101","register_pk":"531670","name":"身延山久遠寺旧書院","kana":"みのぶさんくおんじきゅうしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38155278,"lng":138.42695833,"geo_status":"db","era":"明治9年／平成23年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-122","desc":"大客殿の東北方に建つ。東西棟の入母屋造本瓦葺で、正側面に下屋を付す。内部は上段の間と座敷三室を一列に配し、両側面に畳廊下と縁を通す。長押を二段廻して高くつくった天井、室境を飾る透彫の欄間彫刻など重厚な外観と対比的な内部意匠が特色である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012346"},{"id":"00013386","register_sub_id":"101","register_pk":"368472","name":"身延山久遠寺御真骨堂","kana":"みのぶさんくおんじごしんこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38198333,"lng":138.42592222,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"土蔵造平屋建、銅板葺、建築面積106㎡、木造宝塔付","structure_material":"土蔵造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0149","desc":"仏殿西側の傾斜地に建つ前室廊下付の八角円堂で、外部漆喰塗で東西に唐破風付窓を付す。八角平面の内陣須弥壇に金色の宝塔を安置する。周囲の入側に天女等の彫刻を施した海老虹梁を架ける。軸部、組物、彫刻とも金箔や極彩色を施し、格別な荘厳の堂内を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013386"},{"id":"00012342","register_sub_id":"101","register_pk":"531666","name":"身延山久遠寺御真骨堂拝殿","kana":"みのぶさんくおんじごしんこつどうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38170278,"lng":138.42583056,"geo_status":"db","era":"明治14年／平成13年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-118","desc":"本坊域中央の高台に南面して建つ。桁行三間梁間四間、入母屋造平入で、軒唐破風付の向拝を設ける。尾垂木付二手先の組物、二軒扇垂木の深い軒など禅宗様を基調とし、細部彫刻も秀逸。祖師堂と同じ六〇〇年遠忌の再建で、当時の意匠と造形が凝縮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012342"},{"id":"00012356","register_sub_id":"101","register_pk":"531680","name":"身延山久遠寺三昧堂","kana":"みのぶさんくおんじさんまいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3620","lat":35.38300278,"lng":138.42134167,"geo_status":"db","era":"文政5年(1823)／昭和16年移築","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-132","desc":"西谷の高台に南面して建つ。桁行四間梁間三間、入母屋造妻入、正面に向唐破風の向拝を設ける。後方の奥行三間は増築。側廻りは尾垂木付三手先組物の詰組、向拝廻りを緻密な彫刻で充溢し、内部を二重折上格天井とするなど江戸後期の充実したつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012356"},{"id":"00012352","register_sub_id":"101","register_pk":"531676","name":"身延山久遠寺三門","kana":"みのぶさんくおんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3567","lat":35.37895556,"lng":138.42385556,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積295㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-128","desc":"本坊域への参道口に南面して建つ。本瓦形銅板葺、五間三戸の二階二重門。下層は木鼻付三手先詰組、二軒繁垂木、上層は尾垂木付三手先詰組、二軒扇垂木で、左右の山廊は正面には花頭窓を設ける。規模雄大かつ精緻なつくりで、近代における禅宗様二重門の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012352"},{"id":"00012349","register_sub_id":"101","register_pk":"531673","name":"身延山久遠寺時鐘楼","kana":"みのぶさんくおんじじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38080833,"lng":138.42599167,"geo_status":"db","era":"昭和27年／平成25年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-125","desc":"方一間袴腰付の鐘楼で、屋根は南北棟の入母屋造桟瓦葺。擬宝珠高欄付の縁を三手先腰組で受け、組物間は一二支の彫刻で飾る。上層は粽付円柱を虹梁形頭貫で固め、台輪を廻らして出組の詰組とする。全体にたちの高いつくりで、本坊域入口の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012349"},{"id":"00012359","register_sub_id":"101","register_pk":"531683","name":"身延山久遠寺思親閣仁王門","kana":"みのぶさんくおんじししんかくにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4222","lat":35.39696667,"lng":138.41719722,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-135","desc":"奥之院にある三間一戸八脚門。切妻造瓦棒銅板葺、両端部の前方は土間、後方は板床に壇を設けて仁王像を安置する。軸部は内法虹梁・頭貫で固める。軒廻りは出組に中備蟇股と支輪を付け、妻飾は二重虹梁である。充実した意匠で格調ある表構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012359"},{"id":"00012355","register_sub_id":"101","register_pk":"531679","name":"身延山久遠寺常唱殿","kana":"みのぶさんくおんじじょうしょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3630","lat":35.38160833,"lng":138.42003889,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積341㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-131","desc":"西谷の入口に南面して建つ。入母屋造檜皮葺で、正面に向唐破風の式台玄関を設け、北西に上段の間を接続する。四五畳の広間は祖廟塔に正対する西面を全面ガラス窓とし、折上格天井を張る。復古調の蟇股や舟肘木を用いるなど洗練された意匠の瀟洒な和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012355"},{"id":"00012347","register_sub_id":"101","register_pk":"531671","name":"身延山久遠寺新書院","kana":"みのぶさんくおんじしんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.381325,"lng":138.42694722,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-123","desc":"大客殿東側の人工地盤上に建つ。東西棟の入母屋造桟瓦葺、妻飾は木連格子、側廻りは舟肘木とする。内部は二四畳間を三室並べ、四周に畳縁と縁を廻す。東室と西室には座敷飾を備え、各室とも格天井を高く張る。格式を備えた質の高いつくりの近代書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012347"},{"id":"00012357","register_sub_id":"101","register_pk":"531681","name":"身延山久遠寺水行堂","kana":"みのぶさんくおんじすいぎょうどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3620","lat":35.382875,"lng":138.42118889,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造、瓦葺、面積23㎡、水盤付","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-133","desc":"苦修練行の一つである水行の場で三昧堂の南西方にある。桁行五・七メートル梁間四メートル、東西棟の切妻造桟瓦葺、吹放ち形式で、水盤を据える。軸部は几帳面取の角柱を虹梁形頭貫で固め、出組の詰組に中備蓑束とし、軒支輪を付けるなど丁寧なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012357"},{"id":"00012358","register_sub_id":"101","register_pk":"531682","name":"身延山久遠寺瑞門","kana":"みのぶさんくおんじずいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3620","lat":35.38282222,"lng":138.42138333,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-134","desc":"三昧堂の南東方を区切る一間一戸薬医門。切妻造桟瓦葺で、袖塀を左右に延ばす。親柱と控柱を貫で固め、台輪上に大斗舟肘木で軒桁を受け、親柱と控柱の中間に棟木を通す。柱から組物まで木太くつくり、三昧堂の表構えを重厚に固める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012358"},{"id":"00013393","register_sub_id":"101","register_pk":"368478","name":"身延山久遠寺総門茶屋","kana":"みのぶさんくおんじそうもんちゃや","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4007","lat":35.369275,"lng":138.42659167,"geo_status":"db","era":"明治27年","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0156","desc":"総門内側の参道に西面して建つ。木造平屋建、入母屋造桟瓦葺で正面に下屋を設ける。素木造の簡素な外観で、入口回りの土間を吹放し、内部は二列に並べた和室を基本とする。往時には広大な境内入口で参詣者を接待した施設で、日蓮宗寺院の茶所としても希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013393"},{"id":"00012341","register_sub_id":"101","register_pk":"531665","name":"身延山久遠寺祖師堂及び御供所","kana":"みのぶさんくおんじそしどうおよびごくうしょ","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38195278,"lng":138.42506111,"geo_status":"db","era":"明治14年／平成3年・同6年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"祖師堂 木造平屋建、銅板葺、建築面積851㎡ 御供所 木造平屋建、瓦葺、建築面積32㎡","structure_material":"祖師堂 木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-117","desc":"本坊域の大本堂東に南面して建つ。いわゆる撞木造で、側廻りは二手先組物、妻飾は虹梁大瓶束に蟇股を加え向拝に軒唐破風を付す。宗祖六〇〇年遠忌の再建で、豪壮な外観や広大な中陣を含む深遠な内部、精緻な彫刻で飾る内陣など総本山としての威容を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012341"},{"id":"00013387","register_sub_id":"101","register_pk":"368473","name":"身延山久遠寺祖師堂前香炉屋","kana":"みのぶさんくおんじそしどうまえこうろや","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38168056,"lng":138.42500278,"geo_status":"db","era":"明治12年","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造、銅板葺、面積4.2㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0150","desc":"祖師堂正面に建つ香炉の覆屋。方一間、宝形造瓦棒銅板葺。禅宗様を基調とし、組物は二手先、軒は二軒扇垂木とする。虹梁形内法貫の中央を湾曲させて花頭枠風とし、獅子鼻や中備の龍彫物も緻密で秀逸。鏡天井に躍動的な龍彫刻を飾る。見応えある意匠の小舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013387"},{"id":"00013389","register_sub_id":"101","register_pk":"368474","name":"身延山久遠寺祖廟域水屋","kana":"みのぶさんくおんじそびょういきみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3628","lat":35.38126944,"lng":138.41944167,"geo_status":"db","era":"昭和19年","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造、檜皮葺、面積10㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0152","desc":"祖廟拝殿手前に東西棟で建つ。桁行一間梁間一間、切妻造檜皮葺で、巨石を加工した水盤を据える。四本柱と桁に太い丸太を使い、梁や垂木、切裏甲等も丸太で構成する。丸太主体の簡素な直線的意匠で、良材を選び、施工も丁寧。拝殿と統一感ある社頭景観を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013389"},{"id":"00012354","register_sub_id":"101","register_pk":"531678","name":"身延山久遠寺祖廟塔","kana":"みのぶさんくおんじそびょうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3628","lat":35.38201667,"lng":138.41836667,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"石造平屋建、建築面積11㎡、石柵付","structure_material":"石造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-130","desc":"日蓮聖人が隠棲した草庵跡地である西谷にある。鉄筋コンクリート造、八角形平面で、乱石積基壇の周囲を石柵で囲い、内部に五輪塔を安置する。上すぼまりの塔身は大理石張とし、笠石は軒先上部に反りがつき頂部に相輪を戴せる。高さ一二メートルの壮大な廟塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012354"},{"id":"00013388","register_sub_id":"101","register_pk":"368556","name":"身延山久遠寺祖廟拝殿","kana":"みのぶさんくおんじそびょうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3628","lat":35.38193056,"lng":138.41878333,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0151","desc":"桁行五間梁間二間の背面に突出を設けて凸字形平面とし、切妻造檜皮葺屋根に千鳥破風を飾る。軸部から軒に至るまで丸太を使い、垂木は詰打とする。床は平石敷の立礼式とし、突出部は一段高く張る。簡明で木太い軸部構成による、重厚な土間床の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013388"},{"id":"00012344","register_sub_id":"101","register_pk":"531668","name":"身延山久遠寺大客殿","kana":"みのぶさんくおんじだいきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38129167,"lng":138.42668611,"geo_status":"db","era":"明治19年／明治後期・昭和46年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積531㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-120","desc":"仏殿納牌堂の東に西面して建つ。入母屋造平入の長大な客殿で、内部は二十畳の上段を含む畳敷の広間五室とする。正面中央に向唐破風の式台付大玄関を設け、東端に入母屋の小玄関を配する。雄大かつ豪壮な外観で総本山の接客機能に相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012344"},{"id":"00012351","register_sub_id":"101","register_pk":"531675","name":"身延山久遠寺太子堂","kana":"みのぶさんくおんじたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3567","lat":35.37927778,"lng":138.42357222,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積30㎡","structure_material":"土蔵造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-127","desc":"三門の北西方に東面して建つ。方三間、宝形造桟瓦葺で、正面に切妻起屋根の向拝を付す。側廻りは三段積の布石上に腰石張とし、上部を漆喰塗で軒先まで塗籠める。内部は奥一間の内陣に仏壇を構え、外陣には格天井を張る。太子信仰の様相を伝える堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012351"},{"id":"00012348","register_sub_id":"101","register_pk":"531672","name":"身延山久遠寺大鐘楼","kana":"みのぶさんくおんじだいしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38145,"lng":138.42474444,"geo_status":"db","era":"明治15年／昭和14年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造、瓦葺、面積24㎡","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-124","desc":"祖師堂の前方に建つ方三間の吹放ち形式の鐘楼。東西棟の入母屋造本瓦葺で、切石積基壇に太い円柱を立てて、貫で固めるが、中央間は内法虹梁大瓶束とする。組物は三手先詰組で、二軒繁垂木の深い軒を支えた重厚なつくりであり、丸彫や籠彫の彫刻で要所を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012348"},{"id":"00012343","register_sub_id":"101","register_pk":"531667","name":"身延山久遠寺仏殿納牌堂","kana":"みのぶさんくおんじぶつでんのうはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38157222,"lng":138.42625,"geo_status":"db","era":"昭和6年／平成25年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1016㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-119","desc":"桁行七間梁間六間、向拝三間の仏殿が南面して建ち、東西に納牌堂が附属する。仏殿は側廻り二手先組物で、内部には建登せ柱や虹梁を多用する。近代における諸機能の複合化を入母屋造の仏殿に宝形造の二重屋根の納牌堂が連続した独創的な外観でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012343"},{"id":"00012345","register_sub_id":"101","register_pk":"531669","name":"身延山久遠寺法喜堂","kana":"みのぶさんくおんじほうきどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38095556,"lng":138.426525,"geo_status":"db","era":"明治16年／昭和46年・平成23年改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積625㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-121","desc":"大客殿の南方に西面して建つ。桁行一〇間梁間九間、入母屋造妻入で、内部は正面側の土間部に大黒柱や梁に巨木を用い、重厚な軸組と架構をみせる。出入口両側に連続する花頭窓や妻飾の二重虹梁間に連続する大瓶束など、堂々たる構成の中に近代の意匠が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012345"},{"id":"00013392","register_sub_id":"101","register_pk":"368477","name":"身延山久遠寺発軫閣","kana":"みのぶさんくおんじほっちんかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4007","lat":35.36914167,"lng":138.42603611,"geo_status":"db","era":"元文4年（1739）／昭和55年改修","year":1739,"year_source":"db","year_min":1739,"year_max":1739,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0155","desc":"総門内側で参道に直交する石段上に建つ。入母屋造妻入、向拝付の主体部の前面左右に張出しを設ける。内部は畳敷の内外陣と、左右の脇間からなる。内陣鏡天井に飛天を描き、外陣格天井の格間に龍を陽刻する等豊かな装飾をもつ。山中境内入口に建つ堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013392"},{"id":"00012353","register_sub_id":"101","register_pk":"531677","name":"身延山久遠寺本地堂","kana":"みのぶさんくおんじほんちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3567","lat":35.38261111,"lng":138.42530278,"geo_status":"db","era":"嘉永5年(1852)／平成24年改修","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"本坊域背後に南面して建つ。方形の楼造で、正面中央に蔀戸、側面中央に引違格子戸を入れる。三手先で擬宝珠高欄付の縁を受け、上層は尾垂木付三手先と二軒繁垂木で深い軒をつくる。宝形造の屋根は頂部に宝珠を載せる。均整の取れた外観で細部も充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012353"},{"id":"00011129","register_sub_id":"101","register_pk":"205236","name":"山縣神社手水屋","kana":"やまがたじんじゃちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県甲斐市篠原190-1","lat":35.657319,"lng":138.52181,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造、銅板葺、面積5.1㎡","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0079","desc":"境内南、参道の西に建つ。桁行一間、梁間一間、切妻造、屋根を銅板一文字葺とする。円形の礎石上に丸柱を垂直に立て、長押と桁で固め、豕扠首で棟木を受ける。軒は直材の疎垂木で化粧小舞を見せる。自然石による手水石を据える。本殿などと意匠を統一する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011129"},{"id":"00011130","register_sub_id":"101","register_pk":"205237","name":"山縣神社鳥居","kana":"やまがたじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲斐市篠原190-1","lat":35.657206,"lng":138.521776,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造、高さ6.8m、間口4.5m","structure_material":"鉄筋コンクリート造","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0080","desc":"境内南端の参道入口に建つ。鉄筋コンクリート造、表面モルタル洗出仕上げの神明鳥居で、柱間四・五メートル、高さ六・八メートルの規模を持つ。円柱を掘立柱風に垂直に建て、角材の貫で繋ぎくさびの造形をつくり、丸材の笠木を載せる。近代における鳥居の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011130"},{"id":"00011128","register_sub_id":"101","register_pk":"205235","name":"山縣神社拝殿","kana":"やまがたじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲斐市篠原190-1","lat":35.657753,"lng":138.522282,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0078","desc":"本殿の正面に建つ。桁行三間、梁間二間、切妻造、銅板葺で、礎石建の丸柱、妻面の豕扠首、屋根の千木や堅魚木、破風の鞭掛など本殿と共通の意匠とする。室内床は石敷で、天井は疎垂木と化粧小舞の化粧屋根裏とするが、屋根と傾斜が異なり二重の構造を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011128"},{"id":"00011127","register_sub_id":"101","register_pk":"205234","name":"山縣神社本殿","kana":"やまがたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲斐市篠原190-1","lat":35.657888,"lng":138.522415,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.5㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0077","desc":"江戸時代中期の思想家・山縣大弐を祀る神社の本殿で、境内北奥に南面して建つ。規模は二間四方、銅板葺の神明造で棟に千木・勝男木を飾る。白漆喰の基壇を持ち、身舎は基壇上に土台を置いて柱を立てる。棟持柱を内転とするなど典型的な神明造の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011127"},{"id":"00016511","register_sub_id":"101","register_pk":"574873","name":"頥氣神社菅原社","kana":"いけじんじゃすがわらしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町西寺尾字柳島1006","lat":36.57565389,"lng":138.19637889,"geo_status":"db","era":"天保6年（1835）","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"木造平屋建、板葺、建築面積0.5㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0683","desc":"本殿西側の覆屋内に建つ小規模社殿。総ケヤキの一間社流造板葺で三方に縁を廻らし、正面に木階と浜縁を設ける。庇の虹梁形頭貫は絵様の彫りが深く、木鼻は象鼻とし、上部に波に鶴の彫刻を横溢し意匠を集中する。覆屋内で保存が良く、豊かな装飾を施した小社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016511"},{"id":"00016510","register_sub_id":"101","register_pk":"574872","name":"頥氣神社拝殿及び祝詞殿","kana":"いけじんじゃはいでんおよびのりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西寺尾字柳島1006","lat":36.57565389,"lng":138.19637889,"geo_status":"db","era":"文政3年（1820）／昭和50年代改修","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積92㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0682","desc":"本殿の前方に建つ拝殿及び祝詞殿。横長で大型の向拝付拝殿の背面に祝詞殿を突出し、拝殿は入母屋造茅葺（鉄板仮葺）で祝詞殿は切妻造鉄板葺。拝殿は三方を吹放つ板敷の一室で天井張らず小屋組を現し、祝詞殿は棹縁天井を張る。当社の歴史を伝える中心的社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016510"},{"id":"00016512","register_sub_id":"101","register_pk":"574874","name":"頥氣神社宝蔵庫","kana":"いけじんじゃほうぞうこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市松代町西寺尾字柳島1006","lat":36.57565389,"lng":138.19637889,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0684","desc":"拝殿及び祝詞殿の東に西面して建つ祭礼道具の収納蔵。建ちの高い二階建切妻造平入で、屋根は桟瓦葺の置屋根形式とし、入口上部に下屋を付す。小屋は細い曲がり梁を用いた和小屋。外壁はモルタル塗で腰や鉢巻に目地切を施すなど、近代的な特徴を示す土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016512"},{"id":"00016509","register_sub_id":"101","register_pk":"574871","name":"頥氣神社本殿","kana":"いけじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西寺尾字柳島1006","lat":36.57565389,"lng":138.19637889,"geo_status":"db","era":"文政3年（1820）","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.5㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0681","desc":"松代城跡北方に位置する神社の本殿。南北に長い敷地の奥、高い石垣上に建つ総ケヤキの一間社流造で正面に木階と浜縁を設け、屋根は銅板葺。庇中備や身舎正面の小壁、妻面、脇障子を飾る動植物や雲紋などの華やかな彫刻が目を惹く。地元大工による上質な本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016509"},{"id":"00013543","register_sub_id":"101","register_pk":"504910","name":"上田聖ミカエル及諸天使教会堂","kana":"うえだせいみかえるおよびしょてんしきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市中央三丁目4402-1","lat":36.40280278,"lng":138.25518889,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建一部地階付、瓦葺、建築面積171㎡","structure_material":"木造平屋建一部地階付","registered":"2021.02.04(令和3.02.04)","register_no":"20 － 0567","desc":"市中心部にある木造教会堂。道路に西面して建つ入母屋造妻入で、撞木造とし、四周に下屋を廻して正面に入母屋玄関を付す。内部は面取角柱を立て三廊式とし、欄間や高窓の障子、格天井などに伝統建築の要素を取り入れる。近代和風の教会堂として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013543"},{"id":"00008282","register_sub_id":"101","register_pk":"133924","name":"恵明寺山門","kana":"えみょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西条字表村482","lat":36.55625256,"lng":138.19733999,"geo_status":"db","era":"延宝5年(1677)","year":1677,"year_source":"db","year_min":1677,"year_max":1677,"year_label":null,"structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0365","desc":"伽藍正面に位置する一間棟門。切妻造桟瓦葺。粽付の面取方柱を礎石上に建て、上部に三斗を組み、棟木を支持する。本柱間は楣で固め、男梁女梁を前後に出し、軒桁を支持する。一軒半繁垂木。独特の構造になるが、中備の蟇股や絵様など時代相応である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008282"},{"id":"00008281","register_sub_id":"101","register_pk":"133923","name":"恵明寺鐘楼","kana":"えみょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西条字表村482","lat":36.55621312,"lng":138.19714498,"geo_status":"db","era":"天保4年(1833)","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造2階建、瓦葺、建築面積13㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0364","desc":"本堂の東方、門との間に位置する。桁行一間梁間一間、２階建の鐘楼。入母屋造桟瓦葺。石積基壇上に建ち、柱は四方転びで、直接に桁や梁を支持。軒は一軒疎垂木。１階の下半部を竪板張、他を漆喰仕上げとし、袴腰風に見せる。特異な形態になる鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008281"},{"id":"00008280","register_sub_id":"101","register_pk":"133922","name":"恵明寺本堂","kana":"えみょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西条字表村482","lat":36.55630077,"lng":138.19685357,"geo_status":"db","era":"天保4年(1833)","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0363","desc":"象山東麓の境内中央に位置する。桁行五間梁間六間、入母屋造桟瓦葺で、一重裳階付仏殿風の外観とする。正面中央三間に桟唐戸をたて、両端に花頭窓を穿つ。内部は中央４ｍ四方に几帳面取の方柱を建て、その奥に壇を構える。地方における黄檗宗仏殿の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008280"},{"id":"00014812","register_sub_id":"101","register_pk":"519070","name":"加茂神社上屋","kana":"かもじんじゃうわや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市大字西長野字加茂裏213","lat":36.65643333,"lng":138.17758056,"geo_status":"db","era":"嘉永7年（1854）／明治7年改修","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0634","desc":"境内の西に位置する上屋は、一間社流造の形式で桟瓦葺。組物は大斗実肘木で軒は一軒繁垂木とし、妻飾は棟束に笈形を付す。内部は一室で竿縁天井を張り、床を上下段に分け、上段に本殿を安置する。本格的なつくりとした覆屋で、境内の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014812"},{"id":"00014813","register_sub_id":"101","register_pk":"519071","name":"加茂神社拝殿及び祝詞殿","kana":"かもじんじゃはいでんおよびのりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字西長野字加茂裏213","lat":36.65640833,"lng":138.17769722,"geo_status":"db","era":"明治7年／明治前期・同18年増築、令和2年改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"拝殿 木造平屋建、茅葺（銅板仮葺）、建築面積66㎡ 祝詞殿 木造平屋建、銅板葺、建築面積20㎡","structure_material":"拝殿 木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0635","desc":"入母屋造平入茅葺（銅板仮葺）で、東に軒唐破風付き向拝、西に両下造銅板葺の祝詞殿を付して上屋と接続する。組物は平三斗、軒は一軒扇垂木。三方に高欄付き縁を廻らし脇障子を建てる。内部は一室の畳敷で格天井を張る。向拝廻りを彫刻で飾った華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014813"},{"id":"00014811","register_sub_id":"101","register_pk":"519069","name":"加茂神社本殿","kana":"かもじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字西長野字加茂裏213","lat":36.65643333,"lng":138.17758056,"geo_status":"db","era":"慶應4年（1868）","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0633","desc":"善光寺の南西に位置する神社。上屋内に安置する本殿は東面する一間社流造で、屋根は板を刻んでこけら葺風とした板葺。組物は身舎を出組、庇を出三斗、軒は二軒繁垂木、妻飾は虹梁大瓶束。軒唐破風上に千鳥破風を付し、庇の中備に龍の彫刻を入れ華やかな本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014811"},{"id":"00013108","register_sub_id":"101","register_pk":"368266","name":"旧片山家住宅主屋（小内八幡神社社務所）","kana":"きゅうかたやまけじゅうたくしゅおく（おうちはちまんじんじゃしゃむしょ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県中野市大字安源寺字石原566-1","lat":36.73819722,"lng":138.331625,"geo_status":"db","era":"明治前期／昭和前期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、茅葺（金属板仮葺）、建築面積187㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0553","desc":"中野市市街地西方の小内八幡神社境内にあり、同社神主片山家の住宅として建てられた。当初、屋根は茅葺で、平面は南側下手を土間、上手を四間取の座敷とした。霊壇の間と呼ぶ潔斎の場を持つなど、農家住宅とは異なる社家住宅の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013108"},{"id":"00004545","register_sub_id":"101","register_pk":"105535","name":"旧徳善院庫裏（極意家宿坊）","kana":"きゅうとくぜんいんくり（ごくいけしゅくぼう）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市戸隠3354","lat":36.74158576,"lng":138.08620033,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、茅葺、建築面積305㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"20 － 0183","desc":"旧本堂の東方に南北棟で建つ。桁行１１間梁間７間半規模，入母屋造，茅葺の外観総２階建で，もとは南半を土間・勝手等とし，西北隅に床・書院付きの１２畳半座敷を置く。たちの高い巨大な茅葺屋根が特徴的で，戸隠における宿坊建築の遺構例として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004545"},{"id":"00004544","register_sub_id":"101","register_pk":"105534","name":"旧徳善院本堂（極意家神殿）","kana":"きゅうとくぜんいんほんどう（ごくいけしんでん）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市戸隠3354","lat":36.74169997,"lng":138.08598142,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺一部鉄板葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"20 － 0182","desc":"戸隠神社中社の南に隣接した敷地に位置する。桁行６間半梁間５間規模，寄棟造，茅葺で，中央を仏間（現在は神殿），東を客座敷，西を居間兼書斎とする。文化８年の焼失後の再建と伝え，改造はあるが，大きな茅葺屋根は往時の戸隠の宿坊景観をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004544"},{"id":"00014012","register_sub_id":"101","register_pk":"508272","name":"行善寺本堂","kana":"ぎょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上水内郡信濃町大字古間541","lat":36.80006667,"lng":138.21056111,"geo_status":"db","era":"文政13年(1830)／昭和51年・令和2年改修","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積259㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"20 - 0599","desc":"北国街道古間宿に位置。桁行七間梁間七間、入母屋造鉄板葺で三間向拝を付す。正側面に縁を廻す。軒は斜めの出梁に天井を張り木負を受け化粧軒を出す。内部は前方を外陣、背後中央を内陣、両脇を余間とする真宗の通例をとる。宿場町に建つ近世に遡る真宗寺院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014012"},{"id":"00012526","register_sub_id":"101","register_pk":"367821","name":"熊野出速雄神社随神門","kana":"くまのいずはやおじんじゃずいじんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町豊栄字中ノ峯5454","lat":36.535843,"lng":138.250427,"geo_status":"geocoded","era":"文化14年（1817）頃／昭和54年改修","year":1817,"year_source":"db","year_min":1817,"year_max":1817,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0529","desc":"境内正面の参道上に南面して建つ八脚門。東西棟の切妻造桟瓦葺で、組物は出三斗、軒は二軒繁垂木、中備は蟇股と間斗束、妻飾は二重虹梁で蕪懸魚を吊る。細身ながら具象的で躍動感ある虹梁等の絵様が時代感覚を表している。森厳な境内の表構えを華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012526"},{"id":"00012525","register_sub_id":"101","register_pk":"367820","name":"熊野出速雄神社摂社侍従大神社拝殿","kana":"くまのいずはやおじんじゃせっしゃじじゅうおおかみしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町豊栄字中ノ峯5454","lat":36.535843,"lng":138.250427,"geo_status":"geocoded","era":"弘化3年（1846）頃／明治10年・昭和54年改修","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0528","desc":"皆神山頂に鎮座する神社の摂社で、南面して建つ。桁行三間梁間五間、入母屋造銅板葺で、正面に千鳥破風と軒唐破風の向拝を付す。内部は下拝殿と拝殿に分け、背面の突出部に本殿を安置する。出組、二軒繁垂木で、虹梁絵様など細部に時代の特色をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012525"},{"id":"00005833","register_sub_id":"101","register_pk":"106819","name":"荒神堂","kana":"こうじんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代762","lat":36.569038,"lng":138.202057,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0276","desc":"木造平屋建，桁行７間，梁間３間半，入母屋造，桟瓦葺の妻入で向拝がつく。出組実肘木で中備は蟇股，二軒繁垂木とする。四周に高欄付の縁を巡らす。正面の１間通を吹放ち，入側に格子戸，側面を板戸とする。正面の妻飾りや向拝意匠など，正面を重視した外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005833"},{"id":"00013105","register_sub_id":"101","register_pk":"368263","name":"光林寺経蔵","kana":"こうりんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原2329","lat":36.60151389,"lng":138.12661389,"geo_status":"db","era":"慶応元年（1865）／昭和40年改修","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"土蔵造平屋建、金属板葺、建築面積52㎡、八角輪蔵付","structure_material":"土蔵造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0550","desc":"境内南寄りの石積基壇上に北面して建つ宝形造鉄板葺の経蔵。土蔵造、外壁漆喰塗で軒先まで板軒状に塗込め、正面入口と側面の窓に花頭枠をつくる。内部は一室で、彫刻や塗装により装飾された八角輪蔵を納める。比較的規模が大きく、境内景観を特徴づける経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013105"},{"id":"00013107","register_sub_id":"101","register_pk":"368265","name":"光林寺山門","kana":"こうりんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原2329","lat":36.60183889,"lng":138.12693056,"geo_status":"db","era":"文政9年（1826）","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造、瓦葺、間口3.4m、左右袖塀付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0552","desc":"境内東辺中ほどの入口に東面して構える門。一間薬医門、切妻造桟瓦葺で、側背面の各柱間に虹梁を架けて華やかな絵様を施し、正面の冠木上に絡み合う四頭の龍彫刻を彫るなど、堅牢な軸部を構成するとともに、随所を飾る華やかな彫刻や絵様にも見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013107"},{"id":"00013106","register_sub_id":"101","register_pk":"368264","name":"光林寺鐘楼","kana":"こうりんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原2329","lat":36.60199167,"lng":138.12696667,"geo_status":"db","era":"天保元年（1830）","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造、瓦葺、面積8.9㎡","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0551","desc":"境内北東隅の石垣上に築いた石積基壇に建つ吹放し形式の鐘楼。入母屋造桟瓦葺で、禅宗様を基調とし、組物は出組詰組である。虹梁形内法貫と頭貫の間に龍彫刻、台輪上の組物間の松と鷹の彫刻など、随所を力強い彫刻で飾る。高台の境内のシンボルとなる鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013106"},{"id":"00015446","register_sub_id":"101","register_pk":"533461","name":"光林寺本堂","kana":"こうりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原字境内2329","lat":36.60191389,"lng":138.12654722,"geo_status":"db","era":"寛政12年（1800）／昭和53年改修","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積312㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"20 - 0669","desc":"川中島を見下ろす高台にある浄土宗寺院の本堂。東面して建つ寄棟造茅葺形銅板葺屋根で向拝付き。側柱は角柱、入側柱は円柱で虹梁で繋ぎ、格天井を張る。内外ともに多彩な彫刻で装飾し、向拝の鳳凰彫刻や内部虹梁上の笈形付大瓶束は特に大振りで目を惹く本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015446"},{"id":"00016662","register_sub_id":"101","register_pk":"579146","name":"駒形嶽駒弓神社本殿","kana":"こまがたたけこまゆみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市大字上松字駒形東平1997","lat":36.673531,"lng":138.189704,"geo_status":"db","era":"文久3年（1863）頃／昭和42年改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積46㎡、神殿付","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0686","desc":"善光寺北方の境内に南面する。間口三間奥行四間の前半を南北棟の入母屋造、向拝一間軒唐破風付、後半を東西棟の入母屋造とする撞木造。茅葺（鉄板仮葺）。内部は内外陣に二分し、内陣奥に一間社流造の神殿を配す。屋根形式や神殿を祀る点に地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016662"},{"id":"00014362","register_sub_id":"101","register_pk":"511351","name":"下今井諏訪神社神楽殿","kana":"しもいまいすわじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市大字今井字原田2971-2","lat":36.15876111,"lng":137.91015,"geo_status":"db","era":"万延元年(1860)／明治16年改修","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0607","desc":"下今井の氏神の神楽殿で、鳥居と拝殿の中間に位置する。入母屋造桟瓦葺、軒は出桁で支え元茅葺。正面に龍の鏝絵欄間と虹梁を掲げ、四方吹放ち、腕木で高欄付縁を廻らす。床下に残る炉は祭事用で、水管理の会合も行ったと伝わり、境内の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014362"},{"id":"00014359","register_sub_id":"101","register_pk":"511348","name":"下今井諏訪神社諏訪社","kana":"しもいまいすわじんじゃすわしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井字原田2971-2","lat":36.1589,"lng":137.90975833,"geo_status":"db","era":"寛延3年(1750)／昭和13年改修","year":1750,"year_source":"db","year_min":1750,"year_max":1750,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.0㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0604","desc":"下今井の水田と社叢に囲まれた氏神の本殿。一間社流造で元こけら葺、二軒繁垂木、身舎円柱、向拝角柱で浜縁付。内部は内外陣に分ける。緩い曲りの海老虹梁や絵様等時代相を示し、水引虹梁上の、波に兎の透かし彫り欄間と諏訪の神紋入蟇股は洗練された意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014359"},{"id":"00014360","register_sub_id":"101","register_pk":"511349","name":"下今井諏訪神社八幡社","kana":"しもいまいすわじんじゃはちまんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井字原田2971-2","lat":36.15892222,"lng":137.90976111,"geo_status":"db","era":"寛政2年(1790)／大正4年移築・昭和13年改修","year":1790,"year_source":"db","year_min":1790,"year_max":1790,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.9㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0605","desc":"下今井氏神の諏訪社の北側に並ぶ相殿で、南耕地集落から移築したもの。一間社流造、二軒繁垂木、身舎円柱、向拝角柱で浜縁付。内部は内外陣に分ける。強い曲りの海老虹梁や装飾性の増した絵様等、諏訪社と異なる時代相を示す。向拝欄間に鳳凰の丸彫りを付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014360"},{"id":"00014361","register_sub_id":"101","register_pk":"511350","name":"下今井諏訪神社八坂社","kana":"しもいまいすわじんじゃやさかしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井字原田2971-2","lat":36.15884444,"lng":137.90973333,"geo_status":"db","era":"嘉永4年(1851)／大正4年移築・昭和13年改修","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.4㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0606","desc":"下今井氏神の諏訪社の南に並ぶ相殿で、北耕地集落から移築したもの。一間社流造、二軒繁垂木、身舎円柱、向拝角柱で浜縁付。内部は外陣を広くとる。向拝欄間に立体的な丸彫りの龍を配し、身舎頭貫等の横に潰れた渦の絵様は諏訪社・八幡社とは異なる時代相。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014361"},{"id":"00005811","register_sub_id":"101","register_pk":"106798","name":"常徳院門","kana":"じょうとくいんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市元善町615","lat":36.659523,"lng":138.186508,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0268","desc":"敷地の東辺中央，街路に面して開く薬医門形式の表門である。間口は８尺で，４尺控えて控柱が立つ。屋根は切妻造，桟瓦葺である。男梁の正面側を木鼻に造り，出桁上の組物と実肘木で桁を受けている。門扉は両開の板戸で，左手の脇塀に潜戸を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005811"},{"id":"00010778","register_sub_id":"101","register_pk":"201613","name":"證蓮寺山門","kana":"しょうれんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字寺町1299","lat":36.560879,"lng":138.202658,"geo_status":"db","era":"江戸中期／明治19頃移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0490","desc":"境内の西辺中央に構える。間口二・一メートルの四脚門形式、切妻造桟瓦葺で、棟両端に鯱を飾る。軸部を黒色塗とし、桟唐戸を吊る。彫刻等の装飾を抑えた端正な外観ながら、規模や構造は市内の歴代藩主霊屋の表門と類似し、風格のある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010778"},{"id":"00010776","register_sub_id":"101","register_pk":"201611","name":"證蓮寺聖徳太子堂","kana":"しょうれんじしょうとくたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県長野市松代町松代字寺町1300他","lat":36.56075,"lng":138.202815,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0488","desc":"境内南側に北面して建つ、切妻造妻入、桟瓦葺。正面に向拝状の下屋を付し、妻壁に唐草など、堂内の組物間に雲龍や瑞獣などの鏝絵を施し、巧緻な左官技術を見せると共に、内外を華やかに飾立てる。大火後に市民の浄財により再建された堂で、往時の隆盛を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010776"},{"id":"00010777","register_sub_id":"101","register_pk":"201612","name":"證蓮寺鐘楼","kana":"しょうれんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市松代町松代字寺町1299他","lat":36.5608,"lng":138.202722,"geo_status":"db","era":"大正元頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、面積8.2㎡","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0489","desc":"境内南西隅に位置し、高い亀甲積基壇上に建つ方一間吹放ち形式の鐘楼。南北棟の入母屋造で桟瓦を葺き、軒は二軒繁垂木である。面取角柱を四方転びに立て、柱上に三斗、中備に蟇股を配する。通りからも望見され、松代城下の景観に寄与する鐘楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010777"},{"id":"00010775","register_sub_id":"101","register_pk":"201610","name":"證蓮寺本堂","kana":"しょうれんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代字寺町1299他","lat":36.560942,"lng":138.203036,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積221㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0487","desc":"松代城下南東部の寺町に境内を構える。桁行一四メートルの堂で、正面に一間向拝を付す。平面は標準的な真宗寺院本堂形式で、外陣中央間と矢来内の間に絵様虹梁を架けて結界を表す。棟の短い寄棟造屋根を持ち、松代における寺院本堂の特徴的な外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010775"},{"id":"00015008","register_sub_id":"101","register_pk":"529286","name":"白髯神社拝殿","kana":"しらひげじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市鬼無里日影字祖山4957","lat":36.67226111,"lng":137.99149444,"geo_status":"db","era":"明治11年／大正12年・平成29年改修","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0647","desc":"長野市西方の山間、重文の本殿の東に建つ拝殿。入母屋造平入鉄板葺で正面に軒唐破風付向拝を配し千鳥破風を飾る。柱に直接桁を載せ、軒は二軒繁垂木。三方に擬宝珠高欄付縁を廻らし脇障子を建てる。内部は一室の板敷で竿縁天井。破風を重ね外観華やかな拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015008"},{"id":"00015447","register_sub_id":"101","register_pk":"533462","name":"善敬寺本堂","kana":"ぜんきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市吉田三丁目968","lat":36.66848611,"lng":138.21991389,"geo_status":"db","era":"元文元年（1736）／明治37年・昭和57年改修","year":1736,"year_source":"db","year_min":1736,"year_max":1736,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積621㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"20 - 0670","desc":"北国街道沿いに位置する浄土真宗寺院の本堂。境内東寄りに西面して建つ入母屋造銅板葺で正面に三間向拝を付す。内部は内外陣、左右両余間とし、内外陣廻りに円柱を多用し外陣正側面に広縁と落縁を付す。外陣中央間の鏡天井に描く龍が目を惹く規模雄大な本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015447"},{"id":"00016380","register_sub_id":"101","register_pk":"536447","name":"善光寺雲上殿本殿","kana":"ぜんこうじうんじょうでんほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県長野市箱清水三丁目1775","lat":36.67043056,"lng":138.18866111,"geo_status":"db","era":"昭和24年／昭和63年頃・平成24年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"鉄骨鉄筋コンクリート造及び鉄筋コンクリート造地上3階地下1階建、鉄板葺、建築面積733㎡","structure_material":"鉄骨鉄筋コンクリート造及び鉄筋コンクリート造地上3階地下1階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0674","desc":"善光寺の中軸線の北方、大峰山南麓に位置する納骨堂。設計は沖津清。中央に鉄骨鉄筋コンクリート造鉄板葺の多宝塔を配し、東西に鉄筋コンクリート造二階建の翼堂を延ばした独創的な形式。コンクリートで寺院建築の細部意匠まで巧みに表現した大規模納骨堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016380"},{"id":"00013394","register_sub_id":"101","register_pk":"368479","name":"善光寺鐘楼","kana":"ぜんこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字長野字元善町491イ","lat":36.66122222,"lng":138.18815833,"geo_status":"db","era":"嘉永6年（1853）／大正15年改修","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造、檜皮葺、面積33㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"20 － 0563","desc":"本堂の南東に位置し、切石積基壇上に建つ吹放し形式で、入母屋造檜皮葺の鐘楼。南無阿弥陀仏に因み六本の柱を立て、頭貫の木鼻は獅子の彫刻で飾る。軒は二軒扇垂木で、中央の柱間に鐘釣梁を渡し梵鐘を吊る。雄大な本堂の近傍にあって、境内の一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013394"},{"id":"00013395","register_sub_id":"101","register_pk":"368480","name":"善光寺仁王門","kana":"ぜんこうじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市大字長野字元善町469","lat":36.65848333,"lng":138.18754167,"geo_status":"db","era":"大正7年／昭和52年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"20 － 0564","desc":"本堂正面に伸びる参道上、門前町の中に南面して建つ。三間一戸八脚門、切妻造銅板葺で、正背面に軒唐破風を付す。柱上木鼻の正面を獅子、側面を獏、妻飾を龍の彫刻で飾る。正面側の両脇間に一対の仁王像を安置する。古刹の境内入口を引き締める重厚な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013395"},{"id":"00014816","register_sub_id":"101","register_pk":"519074","name":"前山寺庫裏","kana":"ぜんさんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上田市大字前山字上神戸300","lat":36.34115278,"lng":138.19783611,"geo_status":"db","era":"文政13年(1830)／平成13年改修","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積256㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0638","desc":"本堂東側に玄関を介して南面して建つ、切妻造平入桟瓦葺の庫裏である。建ちの高い妻面には三段に重ねた梁と束、貫を現す。内部は西寄りに出入口を設け、東の土間では縦横に組んだ太い梁組を見せる。本堂、三重塔などとともに、境内の歴史的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014816"},{"id":"00014817","register_sub_id":"101","register_pk":"519075","name":"前山寺玄関","kana":"ぜんさんじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県上田市大字前山字上神戸300","lat":36.34107222,"lng":138.19769167,"geo_status":"db","era":"江戸末期／平成13年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0639","desc":"本堂と庫裏の間に位置する東西棟で、屋根を桟瓦葺とする。南に入母屋造の式台を張出し、内部は北に東西二室を並べ、西室に座敷飾を構える。式台は前面に虹梁形頭貫を渡し、奥に舞良戸を建て、妻飾の大瓶束に大振りな笈形を付すなど豊かな装飾と格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014817"},{"id":"00014818","register_sub_id":"101","register_pk":"519076","name":"前山寺山門","kana":"ぜんさんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上田市大字前山字上神戸300","lat":36.34118056,"lng":138.19728889,"geo_status":"db","era":"江戸後期／昭和8年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、間口2.7m、左右袖塀付","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0640","desc":"本堂西側の石段上部、三重塔の正面に北面して建つ一間一戸の薬医門で、屋根は切妻造茅葺である。軸部太く、本柱、控柱上部を桁で固め、桁上に梁を四筋架けて持ち出し、先端で軒桁を支持する。木太く、質実なつくりの山門で、古刹の境内の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014818"},{"id":"00014815","register_sub_id":"101","register_pk":"519073","name":"前山寺本堂","kana":"ぜんさんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上田市大字前山字上神戸300","lat":36.341175,"lng":138.197475,"geo_status":"db","era":"江戸中期／江戸後期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺、建築面積267㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0637","desc":"独鈷山北麓に位置する真言宗寺院の本堂。境内下段中央に南面して建つ寄棟造茅葺。正面に付す唐破風造向拝は頭貫と虹梁の間を雲竜彫刻で飾る。内部は六間取方丈形式を基本とし、北列東端を座敷二室に分け、南に広縁を通す。大型茅葺本堂が歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014815"},{"id":"00005156","register_sub_id":"101","register_pk":"106146","name":"象山神社絵馬殿","kana":"ぞうざんじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.55957724,"lng":138.1960378,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0224","desc":"境内中央西寄りにある。東面した入母屋造，銅板葺で，低い基壇上に建ち，角柱を立てて舟肘木を受ける。出桁を用いて深い軒をつくる。側廻りは腰と小壁を板張とし，他を開放とする。屋根の妻に木連格子を用いる。休憩所を兼ねた，簡素なつくりの絵馬殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005156"},{"id":"00005157","register_sub_id":"101","register_pk":"106147","name":"象山神社斉館","kana":"ぞうざんじんじゃさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.55959786,"lng":138.19672811,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0225","desc":"境内南，社務所の北東にある。入母屋造，桟瓦葺で，正面に唐破風造の玄関，南に入母屋造，北に切妻造の突出部を各々設ける。真壁造，角柱に舟肘木という和風の外観であるが，たちの高いつくりや縦長窓に加え，内部を洋室とするなど，和洋を組み合わせた建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005157"},{"id":"00005158","register_sub_id":"101","register_pk":"106148","name":"象山神社社務所","kana":"ぞうざんじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.559391,"lng":138.196533,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積229㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0226","desc":"境内南に西面して建つ。入母屋造，銅板葺の南北に細長い建物で，北寄りに切妻造玄関を設ける。南半は西と東に座敷や式台玄関を突出し，複雑な屋根を巧みに処理している。真壁造で，角柱に舟肘木をあげた端正な外観で，床・棚付の座敷等は上質なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005158"},{"id":"00005154","register_sub_id":"101","register_pk":"106144","name":"象山神社拝殿・祝詞殿","kana":"ぞうざんじんじゃはいでん・のりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.55998276,"lng":138.19622086,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0222","desc":"拝殿は南面して建つ向拝付の入母屋造で，両側面後ろ寄りに切妻造の神饌所を設け，後方には切妻造の祝詞殿（幣殿）を突出する。拝殿は正側面とも蔀戸を用い，住宅風である。装飾細部を抑えた簡明な意匠で，複雑で変化に富んだ構成を纏めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005154"},{"id":"00005155","register_sub_id":"101","register_pk":"106145","name":"象山神社宝殿","kana":"ぞうざんじんじゃほうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.559765,"lng":138.196045,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0223","desc":"境内中央西寄りにある。東面した切妻造，銅板葺で，切石積基壇上に建ち，角柱を立てて舟肘木を受ける。外壁は腰までを板張，上部を漆喰壁とし，両側面に縦連子窓を設ける。小規模であるが，通風口や縁・階段の形式等に工夫を凝らしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005155"},{"id":"00005153","register_sub_id":"101","register_pk":"106143","name":"象山神社本殿","kana":"ぞうざんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.56012866,"lng":138.19619562,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0221","desc":"３間社流造，二軒繁垂木，銅板葺である。軸部は身舎が円柱，庇が角柱，組物は実肘木付の三斗組，身舎と庇を水平の繋虹梁で結び，妻飾は虹梁上に蟇股を乗せる。四周に縁を廻し，脇障子はなく，伝統様式に則った本殿建築で，装飾の少ない古風な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005153"},{"id":"00010285","register_sub_id":"101","register_pk":"199058","name":"玉依比賣命神社拝殿","kana":"たまよりひめのみことじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東条字内田443","lat":36.565453,"lng":138.215707,"geo_status":"db","era":"嘉永7年（1854）","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0462","desc":"手前に入母屋造妻入の板の間を置いて向拝を付け、一段高い後方に、間口が広く中央を上段の祝詞所とする入母屋造平入の主体部を建て、さらに中央奥に最上段の二畳を張出す。変化に富んだ平面をもち、巧みに演出された内部空間と複雑な屋根形状をもつ拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010285"},{"id":"00010284","register_sub_id":"101","register_pk":"199057","name":"玉依比賣命神社本殿","kana":"たまよりひめのみことじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東条字内田443","lat":36.565498,"lng":138.21561,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0461","desc":"天王山南麓に東面して建つ三間社流造の本殿で、正面に縁と木階を設ける。身舎柱上に舟肘木を置き、庇柱上の出三斗で海老虹梁尻を受ける。身舎正面は三間とも板唐戸を吊るが、内部は一室で、奥の半間に祭壇を構える。全体に装飾を抑えた、端正な意匠の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010284"},{"id":"00010287","register_sub_id":"101","register_pk":"199060","name":"玉依比賣命神社宗形社拝殿及び本殿覆屋","kana":"たまよりひめのみことじんじゃむなかたしゃはいでんおよびほんでんおおいや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東条字内田443","lat":36.565312,"lng":138.216314,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積13㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0464","desc":"境内東方に南面して建つ。桁行三間梁間二間、寄棟造茅葺（鉄板仮葺）、妻入で、側背面を竪板張、正面は開放とする。床板張の内部は前後二室に分け、上段の後室に本殿を鎮座し、拝殿となる前室との境に格子をたてる。近世の境内の様相を良好に伝える境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010287"},{"id":"00010286","register_sub_id":"101","register_pk":"199059","name":"玉依比賣命神社宗形社本殿","kana":"たまよりひめのみことじんじゃむなかたしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東条字内田443","lat":36.565425,"lng":138.215775,"geo_status":"db","era":"元禄6年（1693）","year":1693,"year_source":"db","year_min":1693,"year_max":1693,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積0.5㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0463","desc":"境内東方の覆屋内に南面して建つ。小規模な一間社流造で、三方に縁を廻らして脇障子をたて、正面に木階と浜床を付け、こけら葺とする。柱は全て角柱で、身舎の組物は三斗、庇は連三斗とし、中備蟇股、妻飾は虹梁大瓶束である。小社ながら本格的な構えの本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010286"},{"id":"00009949","register_sub_id":"101","register_pk":"196096","name":"長明寺経蔵","kana":"ちょうめいじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市松代町東寺尾字屋敷3881-2他","lat":36.57030647,"lng":138.20560434,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積30㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0443","desc":"境内北方に南面して建つ。五・五メートル四方の土蔵造で、出入口と東西面の窓を花頭窓とする。出入口上方には唐草の鏝絵を飾る。内部は煉瓦敷の土間で、六角輪蔵を納める。輪蔵は垂下柱に出組を載せる装飾的なものとする。境内景観を引き締める経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009949"},{"id":"00009950","register_sub_id":"101","register_pk":"196097","name":"長明寺三門","kana":"ちょうめいじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東寺尾字屋敷3881-2他","lat":36.57011,"lng":138.2054594,"geo_status":"db","era":"寛政8","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0444","desc":"桁行三間の楼門で、下層全体を吹放しとする。上層は尾垂木付の三手先を詰組とし、内部の須弥壇に文殊菩薩などを祀る。素木造で、組物や垂木の木口に胡粉を塗る。当地の同時期の寺社建築には珍しく、彫刻を抑え、正統的な様式による力強い造形になる門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009950"},{"id":"00009948","register_sub_id":"101","register_pk":"196095","name":"長明寺本堂","kana":"ちょうめいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東寺尾字屋敷3881-2他","lat":36.5701459,"lng":138.20585682,"geo_status":"db","era":"明和4／明治後期改修","year":1767,"year_source":"db","year_min":1767,"year_max":1767,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積312㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0442","desc":"境内中央に西面して建つ。内陣と両脇間を上段として前面を外陣、さらに正面一間通りを広縁とする。浄土宗寺院本堂の特徴的な平面を示し、内陣廻りは組物や彫刻欄間で荘厳する。虹梁絵様や蟇股の意匠も優秀で、江戸後期の当地域を代表する浄土宗寺院本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009948"},{"id":"00014366","register_sub_id":"101","register_pk":"511355","name":"續麻・今井（兼平）神社神楽殿","kana":"つうそ・いまい（かねひら）じんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市大字今井1077","lat":36.14133333,"lng":137.90234167,"geo_status":"db","era":"嘉永6年(1853)／昭和22年移築","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0611","desc":"續麻社・兼平社の正面の鳥居内側に建つ神楽殿。切妻造平入桟瓦葺で、元は茅葺。正面中央柱間と、背面間口一杯に差鴨居を入れ、北側面西間を開放、他は貫で固める。内部は一室の板敷で天井を張らず小屋を現す。本殿前の歴史的景観を構成し、祭礼空間となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014366"},{"id":"00014364","register_sub_id":"101","register_pk":"511353","name":"續麻・今井（兼平）神社兼平社","kana":"つうそ・いまい（かねひら）じんじゃかねひらしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井1077","lat":36.14154722,"lng":137.9019,"geo_status":"db","era":"天保4年(1833)／昭和35年改修","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.4㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0609","desc":"上今井の氏神を祀る本殿。續麻社の南に並ぶ。一間社流造銅板葺、正面に唐破風、千鳥破風を重ねる。内部は内外陣に分け、脇障子と腰組付の縁を三面に廻す。向拝柱筋と菖蒲桁筋に各々精緻な彫刻を施した手挟みを付し、虹梁欄間の龍彫刻等全体を華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014364"},{"id":"00014365","register_sub_id":"101","register_pk":"511354","name":"續麻・今井（兼平）神社神明社","kana":"つうそ・いまい（かねひら）じんじゃしんめいしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井1077","lat":36.14146944,"lng":137.90183611,"geo_status":"db","era":"安永9年(1780)／天保12年（1841）改修・大正4年・昭和22年移築","year":1780,"year_source":"db","year_min":1780,"year_max":1780,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0610","desc":"上今井の氏神を祀る神社に合祀した神明社で、兼平社の南に建つ。一間社見世棚造、切妻造平入銅板葺、柱は床下を八角とした円柱で、梁、桁を架けて束で棟木を支え板軒とする。正面格子戸で、内部は内外陣に分けて宮殿を安置する。素木造で簡明な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014365"},{"id":"00014363","register_sub_id":"101","register_pk":"511352","name":"續麻・今井（兼平）神社續麻社","kana":"つうそ・いまい（かねひら）じんじゃつうそしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井1077","lat":36.14159444,"lng":137.90192222,"geo_status":"db","era":"安政6年(1859)／昭和10年改修・同22年移築","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.1㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0608","desc":"上今井の氏神を祀る本殿。兼平社の北に並ぶ。一間社流造銅板葺、二軒繁垂木、三面切目縁で脇障子付、階、浜縁を付す。曲りの強い海老虹梁で向拝を付し、正面建具は青海波の格子戸を建て、内部は内外陣に分ける。向拝水引虹梁や手挟等を彫刻で華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014363"},{"id":"00012527","register_sub_id":"101","register_pk":"367822","name":"典厩寺閻魔堂","kana":"てんきゅうじえんまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井杵淵字中村999","lat":36.57666,"lng":138.18428,"geo_status":"geocoded","era":"万延元年（1860）","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0530","desc":"川中島古戦場の南方にある曹洞宗寺院の仏堂で、境内東南隅に北面して建つ。正面・側面とも6･2メートルの宝形造桟瓦葺で、裳階を廻し、内部には巨大な閻魔像を安置する。舟肘木の組物や登梁風の大疎垂木など独特な形態で、地域の歴史と信仰の様相を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012527"},{"id":"00012528","register_sub_id":"101","register_pk":null,"name":"典厩寺山門","kana":"てんきゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井杵淵字中村999、1000-イ","lat":36.57666,"lng":138.18428,"geo_status":"geocoded","era":"江戸中期／明治19年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0531","desc":"3代松代藩主・真田幸道霊屋の表門を移築したもので、境内東面南寄りに建つ。切妻造桟瓦葺の四脚門で、軸部は五平の本柱と冠木を組んで梁をかけ、梁上の大きな蟇股で棟木を受ける。簡明ながら良材を多用した丁寧なつくりで、門前景観を格式高く演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012528"},{"id":"00010139","register_sub_id":"101","register_pk":"197972","name":"徳運寺庫裏","kana":"とくうんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市大字入山辺字院地4527-1","lat":36.221275,"lng":138.045188,"geo_status":"db","era":"安政3／平成5改修","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積428㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0449","desc":"本堂の東側に式台を介して南北棟で建つ。当地方に特徴的な本棟造民家に類した形式を持ち、桁行一二間、梁間八間と大規模になる。南寄りを土間の玄関とし、床上部は、奥三室の座敷の前面に、オエ等各室を配する。当地域における江戸末期の大型禅院庫裏の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010139"},{"id":"00010140","register_sub_id":"101","register_pk":"197973","name":"徳運寺山門及び高塀","kana":"とくうんじさんもんおよびたかべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市大字入山辺字院地4526","lat":36.221064,"lng":138.044826,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"山門 木造、瓦葺、間口4.2m 高塀 木造、瓦葺、総延長8.2m","structure_material":"山門 木造","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0450","desc":"境内の南正面を画す門と塀。山門は薬医門形式で、梁の持送りや妻飾の笈形に彫りの深い彫刻を施す。山門の左右には高塀が取付き、右方三・六メートル、左方四・六メートルを測る。高塀は真壁とし、壁面を漆喰で仕上げる。凛とした佇まいで、境内正面を引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010140"},{"id":"00010138","register_sub_id":"101","register_pk":"197971","name":"徳運寺本堂","kana":"とくうんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市大字入山辺字院地4526","lat":36.221406,"lng":138.044819,"geo_status":"db","era":"嘉永6／昭和50改修","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積392㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0448","desc":"寄棟造銅板葺の方丈型本堂で、南面して建つ。平面は八間取の前面に二間幅の広縁を通す、大型の堂である。南西隅に鎮守堂を張出し、金比羅大権現等を祀る。全体に装飾は抑えめで、側廻りは柱上に台輪を廻らして三斗を置く。起りのある大屋根が風格を醸す本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010138"},{"id":"00005771","register_sub_id":"101","register_pk":"106759","name":"長野聖救主教会","kana":"ながのせいきゅうしゅきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字西長野6","lat":36.656319,"lng":138.182053,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積138㎡","structure_material":"煉瓦造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0264","desc":"煉瓦造平屋建で北面して建つ。奥行１４．５ｍの単廊式会堂に祭壇を突出する。屋根は切妻造，鉄板葺である。正面は尖頭アーチの入口上部にバラ窓を飾り，両脇に尖頭アーチの窓を開く，側壁と隅部にはバットレスをつける。西洋中世風の小会堂の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005771"},{"id":"00014485","register_sub_id":"101","register_pk":"513899","name":"日本聖公会中部教区稲荷山諸聖徒教会","kana":"にっぽんせいこうかいちゅうぶきょうくいなりやましょせいときょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県千曲市大字稲荷山字伊勢宮198-2他","lat":36.53153889,"lng":138.10249167,"geo_status":"db","era":"昭和8年／同62年改修、平成15年増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積167㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"20 - 0630","desc":"稲荷山宿近くの善光寺街道沿いにある教会。基壇に建つ鉄筋コンクリート造切妻造で、両側面にバットレス風柱形を付し、外壁モルタル仕上。単廊式で軸線上に会衆席・至聖所・聖所を並べ、地下に納骨堂を配す。地方の近代鉄筋コンクリート造教会として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014485"},{"id":"00011958","register_sub_id":"101","register_pk":"211102","name":"日本聖公会中部教区飯山復活教会","kana":"にほんせいこうかいちゅうぶきょうくいいやまふっかつきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県飯山市大字飯山2278-イ-1","lat":36.854274,"lng":138.36443,"geo_status":"db","era":"昭和7年／平成16年増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"20-517","desc":"切妻造、妻入で棟上に鐘塔を戴き、外壁は下見板張に尖頭アーチ窓を並べる。玄関ポーチの入口を尖頭アーチ形の洗出し仕上げとし、下見板を扇状に張る。単廊式で会衆席と前室、祭壇等を配し、会衆席と前室は当初から畳敷であった。昭和初期の瀟洒な木造教会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011958"},{"id":"00012735","register_sub_id":"101","register_pk":"367638","name":"日本聖公会中部教区岡谷聖バルナバ教会","kana":"にほんせいこうかいちゅうぶきょうくおかやせいばるなばきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県岡谷市本町四丁目4840-2他","lat":36.06472889,"lng":138.04668583,"geo_status":"db","era":"昭和3年／昭和39年増築・平成25年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋一部2階建、金属板葺、建築面積121㎡","structure_material":"木造平屋一部2階建","registered":"2019.03.29(平成31.03.29)","register_no":"20 － 539","desc":"市中心部にある単廊式の木造教会。切妻造妻入、南正面の中央に切妻屋根の玄関ポーチ、左右に招屋根風の張出しを設けた連山のような印象的な立面で、玄関ポーチ妻の社寺風の装飾や会衆席の畳敷など和風の要素を取り入れる。地域に根ざした独特な姿の教会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012735"},{"id":"00013730","register_sub_id":"101","register_pk":"505267","name":"日本聖公会松本聖十字教会","kana":"にほんせいこうかいまつもとせいじゅうじきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市開智一丁目200-1","lat":36.24033889,"lng":137.96548889,"geo_status":"db","era":"明治43年／昭和32年移築改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"20 － 569","desc":"松本城北西に南面して建つ木造教会。急勾配の切妻屋根に赤色瓦を葺き、南東側に鐘塔を建てる。三廊式で小屋はシザーストラスを組む。身廊側面や窓に尖頭アーチを用いるなどゴシックを基調とする一方、祭壇の小屋に絵様付木鼻を付すなど独自の意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013730"},{"id":"00009947","register_sub_id":"101","register_pk":"196094","name":"梅翁院山門","kana":"ばいおういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字田町984-2他","lat":36.56640521,"lng":138.20370225,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.7m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0441","desc":"本堂南正面に南面して構える。間口二・七メートルの一間薬医門で、東西に袖塀を附属し東側に潜戸を開く。拳鼻付の大瓶束で棟木を受け、軒は二軒繁垂木とする。扉には八双金具と乳金具を打つ。簡明ながら重厚な意匠を持ち、伽藍の正面を飾るに相応しい門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009947"},{"id":"00009946","register_sub_id":"101","register_pk":"196093","name":"梅翁院本堂","kana":"ばいおういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字田町984-2他","lat":36.56669788,"lng":138.20368856,"geo_status":"db","era":"文久元／昭和28・昭和60頃改修","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0440","desc":"松代城下東寄りに構える境内に、南面して建つ。六間取方丈型の平面とし、前土間を持つ。組物は、側廻りでは柱上に舟肘木を置き、内陣は三斗を組む。要所に虹梁を架けて装飾とするほかは簡素な意匠とする。当地における近世の曹洞宗寺院本堂の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009946"},{"id":"00015010","register_sub_id":"101","register_pk":"529288","name":"離山神社拝殿・祝詞殿及び本殿上屋","kana":"はなれやまじんじゃはいでん・のりとでんおよびほんでんうわや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町清野字離山1917","lat":36.56071111,"lng":138.19368333,"geo_status":"db","era":"文化13年（1816）／平成27年改修","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0649","desc":"境内南辺に建つ入母屋造東西棟の拝殿の北に、両下造南北棟の祝詞殿と切妻造東西棟の本殿覆屋を接続する複合社殿で屋根総桟瓦葺とする。拝殿は正面に向拝を付して、側面は斜面上に縁を張出し、懸造とする特異な形式。丘上の高低差を巧みに利用した雄大な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015010"},{"id":"00015009","register_sub_id":"101","register_pk":"529287","name":"離山神社本殿","kana":"はなれやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町清野字離山1917","lat":36.56077778,"lng":138.19371111,"geo_status":"db","era":"江戸中期／文化13年(1816)改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、こけら葺、建築面積3.4㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0648","desc":"松代城跡南西の小山に鎮座する本殿。境内北の覆屋内に南面して建つ、一間社流造こけら葺で三方に刎高欄付縁を廻らし、脇障子を建てる。身舎桁下に連三斗を組み軒は二軒繁垂木。妻飾は束を大瓶束とした豕扠首形式。全体に塗装彩色を残し、丁寧なつくりの本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015009"},{"id":"00005183","register_sub_id":"101","register_pk":"106173","name":"法蔵寺庫裏","kana":"ほうぞうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科5716","lat":36.30242269,"lng":137.90577938,"geo_status":"db","era":"江戸中期／明治4・40移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積402㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0251","desc":"境内中央の南寄りにある。切妻造，妻入で，北妻面を正面とし，四周に下屋を廻し，玄関に軒唐破風を設ける。軒は出桁造，真壁造であるが，北と西の外壁は軒裏まで漆喰塗とする。規模大で，内外ともよく当初形式を保持しており，この地域における庫裏の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005183"},{"id":"00005184","register_sub_id":"101","register_pk":"106174","name":"法蔵寺書院","kana":"ほうぞうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科5716","lat":36.30230862,"lng":137.9059378,"geo_status":"db","era":"江戸中期／明治4・40移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0252","desc":"庫裏の南東隅にある。南北棟の切妻造で，西面に下屋を設け，屋根は桟瓦葺である。平面は１０畳間の２室に縁を廻した形式で，奥に床・棚・付書院を備える。規模は小さいが，良材を多用した丁寧なつくりで，この地域における書院建築の傾向を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005184"},{"id":"00005182","register_sub_id":"101","register_pk":"106172","name":"法蔵寺鐘楼門","kana":"ほうぞうじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科5716","lat":36.30258344,"lng":137.90544165,"geo_status":"db","era":"寛政5頃","year":1793,"year_source":"db","year_min":1793,"year_max":1793,"year_label":null,"structure":"木造、2階2重、瓦葺、建築面積75㎡","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0250","desc":"境内正面の西入口にある。３間１戸２階２重門で，入母屋造，桟瓦葺屋根を架ける。低い切石積基壇上に建ち，初層は円柱を立て丸桁を受ける。上層は吹放しで，円柱に出組をあげ，格天井を張って中央に銅鐘を吊る。彫刻等の細部から大隅流棟梁の作と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005182"},{"id":"00005185","register_sub_id":"101","register_pk":"106175","name":"法蔵寺土蔵","kana":"ほうぞうじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科5716","lat":36.30223576,"lng":137.90582842,"geo_status":"db","era":"安政元","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0253","desc":"庫裏の南後方にあり，化粧棟木下端の墨書から年代が明確。東西棟の２階建土蔵造で，屋根は置屋根式とし，北面に下屋を設け，桟瓦葺とする。下屋は３方を壁で厳重に囲い，戸口を２カ所を設ける。内壁は化粧板張とするなど，全体に堅牢で丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005185"},{"id":"00005140","register_sub_id":"101","register_pk":"106130","name":"祝神社拝殿","kana":"ほうりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代567","lat":36.56340328,"lng":138.20322097,"geo_status":"db","era":"文化12","year":1815,"year_source":"db","year_min":1815,"year_max":1815,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0208","desc":"桁行７間，梁間３間規模，入母屋造，桟瓦葺，妻入。正面向拝は唐破風付きで，彫刻で飾る。内部は２室で，奥間の床を一段高くする。正面１間を吹放し，３方に縁を廻す。鬼瓦には六連銭を表す。本殿と同年代の建立で，一体となって歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005140"},{"id":"00005139","register_sub_id":"101","register_pk":"106129","name":"祝神社本殿","kana":"ほうりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代567","lat":36.56342549,"lng":138.20338191,"geo_status":"db","era":"文化9","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0207","desc":"銅板葺の二間社流造の社殿で，縁及び浜床を高くとり，均整のとれた外観を示す。脇障子に唐獅子を表し，向拝中備の龍や木鼻の象など，各所に彫物をあしらい華やかに飾る。松代町方の総鎮守神，産土神として地元で親しまれてきた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005139"},{"id":"00004959","register_sub_id":"101","register_pk":"105949","name":"無量寺庫裏","kana":"むりょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36109889,"lng":137.99742655,"geo_status":"db","era":"文化7～9","year":1811,"year_source":"estimated","year_min":1810,"year_max":1812,"year_label":"文化7～9","structure":"木造平屋一部2階建、茅葺（鉄板仮葺）、建築面積337㎡","structure_material":"木造平屋一部2階建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0195","desc":"本堂の東にあり，玄関付の廊下で接続する。南北に細長い平面で，北半が居室部，南半が土間になり，一部２階を設け，西面中央に出入口をつける。屋根は寄棟造，茅葺（鉄板覆）とする。たちの高い軸部や側廻りの壁面構成など，造形的にも本堂との共通性がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004959"},{"id":"00004963","register_sub_id":"101","register_pk":"105953","name":"無量寺衆寮","kana":"むりょうじしゅりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36121169,"lng":137.99691597,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積94㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0199","desc":"本堂の南西方にある。東西棟の寄棟造，茅葺（鉄板覆），桁行９間半，梁間３間で，中央に幅１間半の通路を設け，左右は部屋とし，一時は住居に用いた。たちの高い軸組，出桁造の軒廻りなどから，本堂などと同時期の建築と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004963"},{"id":"00004960","register_sub_id":"101","register_pk":"105950","name":"無量寺鐘楼堂","kana":"むりょうじしょうろうどう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36113938,"lng":137.99710381,"geo_status":"db","era":"文化12","year":1815,"year_source":"db","year_min":1815,"year_max":1815,"year_label":null,"structure":"木造、瓦葺、建築面積7.4㎡","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0196","desc":"本堂の南正面にある方一間袴腰付の鐘楼で，低い切石積基壇上に建つ。屋根は南北棟の切妻造，桟瓦葺，八角形柱をたて吹放ちとし，四周に高欄を廻す。両側は野物風の梁上に棟束をたて，彫刻を施した笈形を付ける。棟札から大工は出雲崎の宮下治郎七と判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004960"},{"id":"00004962","register_sub_id":"101","register_pk":"105952","name":"無量寺土蔵","kana":"むりょうじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36095922,"lng":137.99743117,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0198","desc":"庫裏南東に隣接して建ち，立地上，南側の基礎は谷積で高く築いている。土蔵造２階建，東西棟の切妻造，桟瓦葺で，北面に戸口を設け，庇をつける。外壁は南・西・北面の腰を海鼠壁とし，垂木まで漆喰塗とするが，開口部は設けない。厳重で堅牢なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004962"},{"id":"00004961","register_sub_id":"101","register_pk":"105951","name":"無量寺宝物殿","kana":"むりょうじほうもつでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.3613209,"lng":137.99767236,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0197","desc":"庫裏の北方に位置し，棟札から建築年代が明確である。土蔵造２階建，東西棟の切妻造，桟瓦葺で，南面中央に戸口を設け，庇をつける。外壁は漆喰塗で４周の腰を海鼠壁とし，軒廻りは鉢巻を廻す。戸口や窓の開口部には縁取をつける。全体に丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004961"},{"id":"00004958","register_sub_id":"101","register_pk":"105948","name":"無量寺本堂","kana":"むりょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36130745,"lng":137.99736793,"geo_status":"db","era":"文化7～9","year":1811,"year_source":"estimated","year_min":1810,"year_max":1812,"year_label":"文化7～9","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積322㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0194","desc":"曹洞宗寺院の本堂で，南面して建つ。正面側に土間と広縁を設けた八間取平面で，屋根は寄棟造，茅葺（鉄板覆）とする。たちの高い軸組とし，出桁造で深い軒をつくる。外観は装飾が少なく簡素であるが，内陣廻りには江戸後期らしい多彩な彫物を用いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004958"},{"id":"00014156","register_sub_id":"101","register_pk":"508786","name":"明徳寺山門","kana":"めいとくじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町豊栄字菖蒲沢2833","lat":36.54278889,"lng":138.23165,"geo_status":"db","era":"正徳3年(1713)頃／昭和38年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"20-0601","desc":"本堂の正面に建つ３間１戸楼門の鐘楼門。礎石上に丸柱を立て、貫、虹梁等で固め、挿肘木と木鼻付頭貫を延ばし２階の縁葛を受ける。二階は中央間に開口を開け、両脇に花頭窓を付す。屋根は入母屋造桟瓦葺だが旧は茅葺で、参道石段上の雄大な景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014156"},{"id":"00014155","register_sub_id":"101","register_pk":"508785","name":"明徳寺本堂","kana":"めいとくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町豊栄字菖蒲沢2833","lat":36.54278333,"lng":138.23200278,"geo_status":"db","era":"正徳3年(1713)頃／宝暦3年(1753)・明治中期・昭和38年・同50年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積276㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"20-0600","desc":"松代南東の旧関屋村に位置。桁行９間梁間７間、寄棟造鉄板葺で箱棟を高く掲げ、西面する。内部は六室構成に加えて南列に座敷を設け、前面土間を室に改修する。中央奥の内陣回りに丸柱を立て須弥壇を据える。曹洞宗の典型的平面を持つ江戸中期に遡る本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014155"},{"id":"00016667","register_sub_id":"101","register_pk":"579151","name":"湯福神社拝殿及び祝詞殿","kana":"ゆぶくじんじゃはいでんおよびのりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県長野市箱清水三丁目1-2","lat":36.66315,"lng":138.184919,"geo_status":"db","era":"文政12年（1829）／明治12年、大正11年増築、昭和37年改修","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積126㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0691","desc":"本殿前面に南面する。桁行三間梁間五間、入母屋造茅葺形銅板葺、向拝一間、軒唐破風付。内部は横長平面で格天井の拝殿の後方に凸型平面の祝詞座を上段として張出し、西に神饌所を設ける。向拝の虹梁形の頭貫と桁の間を仙人彫刻で埋めるなど見応えあるつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016667"},{"id":"00016666","register_sub_id":"101","register_pk":"579150","name":"湯福神社本殿","kana":"ゆぶくじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市箱清水三丁目1-2","lat":36.663273,"lng":138.184941,"geo_status":"db","era":"文久3年（1863）／明治12年増築","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0690","desc":"善光寺北西の境内奥に南面する三間社流造、銅板葺。擬宝珠高欄付縁を廻らし、脇障子を建てる。庇は間口三間分を広い一間として中備に龍彫刻を飾る。妻は二重虹梁大瓶束を出組で持出し、虹梁間に力士を配す。大規模で、幕末らしい華やかな彫刻で飾られた本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016666"},{"id":"00005453","register_sub_id":"101","register_pk":"106441","name":"皆楽座","kana":"かいらくざ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県各務原市鵜沼羽場町1-217","lat":35.40437998,"lng":136.9213839,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"21 － 0081","desc":"市東部の津島神社境内南寄りに建つ。桁行１５ｍ，梁間１０ｍとした切妻造，桟瓦葺，妻入で，正面以外の三方に下屋を廻す。舞台正面の軒を彫刻持送板で出桁を支えて高くし，本殿に向かって構える。囃子座，楽屋，廻舞台，奈落を完備した本格的なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005453"},{"id":"00007031","register_sub_id":"101","register_pk":"108013","name":"加佐美神社拝殿","kana":"かさみじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県各務原市蘇原古市場町5-1-1","lat":35.42249304,"lng":136.8654821,"geo_status":"db","era":"延享3／文政2・天保2改修","year":1746,"year_source":"db","year_min":1746,"year_max":1746,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0159","desc":"本殿と幣殿の南、一段下がった位置に石積基壇上に建つ。入母屋造桟瓦葺。桁行５間梁間２間、全面板床で、棹縁天井。小壁を板壁とし、周囲の内法貫下は開放とする。両端を根肘木で受ける虹梁を正・背面中央間に一段高く架けるなど、割拝殿の名残を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007031"},{"id":"00007030","register_sub_id":"101","register_pk":"108012","name":"加佐美神社幣殿","kana":"かさみじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市蘇原古市場町5-1-1","lat":35.42261179,"lng":136.86547496,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0158","desc":"本殿の正面に建つ、桁行１１ｍ梁間５．１ｍの幣殿。切妻造桟瓦葺とし、中央間を切り上げ、棟を高くする。正面は中央間が約１ｍ奥に入り、引違格子戸を建て、両脇間は格子戸嵌殺しとする。中央間のみ柱上に舟肘木。本殿正面の厳粛な礼拝空間を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007030"},{"id":"00007029","register_sub_id":"101","register_pk":"108011","name":"加佐美神社本殿","kana":"かさみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県各務原市蘇原古市場町5-1-1","lat":35.422676,"lng":136.865479,"geo_status":"db","era":"貞享4／江戸後期改修","year":1687,"year_source":"db","year_min":1687,"year_max":1687,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0157","desc":"加佐美山南麓に南面する。規模の大きな３間社流造。屋根檜皮葺。正面に千鳥破風と軒唐破風を付ける。身舎の正・側面に高欄付の切目縁をまわし、正面に木階と浜床を設ける。円柱上に支輪付出組とし、二重虹梁大瓶束の妻を一段持ち出す。見応えのある構造になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007029"},{"id":"00006481","register_sub_id":"101","register_pk":"107464","name":"上の島神明神社社務所","kana":"かみのしましんめいじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.36854428,"lng":136.83911034,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0140","desc":"境内の中央西方に東面して建つ。桁行６間、梁間３間で、入母屋造桟瓦葺とする。南北に３室が並び、北が土間と板敷、中央が式台と８畳、南がトコと違棚を構える座敷とし、座敷には縁がまわる。緩やかな勾配の屋根をもち、丁寧に造られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006481"},{"id":"00006485","register_sub_id":"101","register_pk":"107468","name":"上の島神明神社太鼓橋","kana":"かみのしましんめいじんじゃたいこばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.3685919,"lng":136.83924021,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造桁橋、橋長5.7m、幅員2.7m","structure_material":"石造桁橋","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0142","desc":"境内の中央、拝殿の前方に位置し、池に架かる。石造桁橋で、アーチの高さは１．５ｍで、中央を束で支え、束両脇には唐草文様を彫り出す石版を飾る。橋両端には擬宝珠高欄を付け、架木を蟇股状の石で支える。大きく反り上がり、躍動的な雰囲気を漂わせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006485"},{"id":"00006482","register_sub_id":"101","register_pk":"107465","name":"上の島神明神社手水舎","kana":"かみのしましんめいじんじゃちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.36865766,"lng":136.83916507,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、面積7.0㎡","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0141","desc":"境内の西側、社務所の北に位置する。桁行１間、梁間１間の規模で、切妻造桟瓦葺とする。柱は面取方柱で内転びとし、内法貫と頭貫で固め、柱上に大斗肘木を組む。妻は虹梁上に大瓶束をたて、軒は一軒疎垂木。虹梁や木鼻の絵様などは穏やかな意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006482"},{"id":"00006483","register_sub_id":"101","register_pk":"107466","name":"上の島神明神社鳥居","kana":"かみのしましんめいじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.368103,"lng":136.839233,"geo_status":"db","era":"昭和10／平成7修理","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、高さ8.2m、幅6.0m","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0144","desc":"境内の正面に建ち、木製で表面を銅板で覆う。幅６．０ｍ、高さ８．２ｍと規模が大きい。柱は径７０ｃｍの円柱で、足下には礎石状に石を巻き、柱上に笠木をのせ、貫で固め、貫は柱内で止まる。簡潔な意匠であるが、大規模で風格がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006483"},{"id":"00006484","register_sub_id":"101","register_pk":"107467","name":"上の島神明神社蕃塀","kana":"かみのしましんめいじんじゃばんぺい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.36843233,"lng":136.83923533,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造目隠塀、延長3.8m","structure_material":"石造目隠塀","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0143","desc":"敷地中央、太鼓橋の前方に位置する。石造の蕃塀。基壇上に円柱の主柱を立て、入母屋造屋根を架け、柱間には連子窓をあけ、上部には波に龍、腰壁には虎と唐獅子の彫刻を置く。前後に控えとして擬宝珠柱を設ける。規模が大きく、豊かな彫物を飾るなど特異な蕃塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006484"},{"id":"00006480","register_sub_id":"101","register_pk":"107463","name":"上の島神明神社幣殿","kana":"かみのしましんめいじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.368973,"lng":136.839264,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0139","desc":"幣殿は本殿の前に南北棟として建つ。桁行３間、梁間３間の規模で、入母屋造妻入銅板葺とする。正・背面中央を開口とし、他は格子窓で腰板壁とし、周囲に縁を廻す。方柱で平三斗を組み、軒は二軒繁垂木である。木鼻の彫物以外は装飾を控え、堅実な意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006480"},{"id":"00006479","register_sub_id":"101","register_pk":"107462","name":"上の島神明神社本殿","kana":"かみのしましんめいじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.369034,"lng":136.83926472,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、銅板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0138","desc":"南面する浜縁付一間社流造で、側・背面を２間とし、屋根は銅板葺とする。身舎は円柱で出組、向拝は几帳面取方柱で連三斗を２段に組み、軒は二軒繁垂木。中備や脇障子ほかに瑞龍や植物、雲紋などの彫刻が飾られる。構造と装飾がバランスよくまとめられた遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006479"},{"id":"00000827","register_sub_id":"101","register_pk":"101817","name":"熊野神社目隠門","kana":"くまのじんじゃめかくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県加茂郡八百津町八百津4102-1","lat":35.47591831,"lng":137.1399211,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"石造目隠塀，幅3m，高さ2m","structure_material":"石造目隠塀","registered":"1998.10.09(平成10.10.09)","register_no":"21 － 0017","desc":"拝殿の真正面にあって，これを塞ぐように建つ石造の目隠門。門は左右の親柱に付属する小さな控柱で支え，屋根をかける簡素な形式になる。壁面の上部は波に龍を浮き彫りにし，下部には獅子のレリーフで飾り，中央部は連子をはめる特異な門として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000827"},{"id":"00009606","register_sub_id":"101","register_pk":"194602","name":"酒波神社鐘楼","kana":"さかなみじんじゃしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県瑞浪市日吉町字南垣外4088","lat":35.40744738,"lng":137.24372428,"geo_status":"db","era":"江戸中期／明治42移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、銅板葺、建築面積8.9㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"21 － 0215","desc":"本殿の東方に東西棟で建つ。方一間袴腰付鐘楼で、入母屋造とし、四周に縁を廻す。方柱を腰貫、頭貫と台輪で固め、三斗組とし、中備に平三斗を置く。軒は二軒繁垂木で、妻は豕扠首。廃仏毀釈により梵鐘を失った後は祭器蔵と称し、現在も下層に神輿を納める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009606"},{"id":"00009605","register_sub_id":"101","register_pk":"194601","name":"酒波神社本殿","kana":"さかなみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県瑞浪市日吉町字南垣外4088","lat":35.40734744,"lng":137.24351964,"geo_status":"db","era":"元禄15","year":1702,"year_source":"db","year_min":1702,"year_max":1702,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"21 － 0214","desc":"境内北方に建ち、三間社流造銅板葺で、三方に高欄付切目縁を廻し、正面に一間幅の木階を設ける。全体を赤色塗とし蟇股彫刻に彩色を施す。頭貫木鼻に雲紋を陽刻し、妻飾は虹梁を出組で二段持出し、意匠を凝らす。建立年代の判明する神社本殿として市内最古。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009605"},{"id":"00014385","register_sub_id":"101","register_pk":"511374","name":"真龍寺玄関及び茶室","kana":"しんりゅうじげんかんおよびちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市長良2509-1","lat":35.45489722,"lng":136.785475,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"21 - 0295","desc":"百々ヶ峰南麓の浄土真宗寺院の本堂と庫裏を繋ぐ渡り廊下と、その南側の唐破風玄関、北側の切妻造茶室からなる建物。茶室は四畳半で西面に床構え、床脇に円窓、東に水屋を配す。茶室と廊下境壁の腰を無双窓として来客を知る。寺院の機能的な玄関と接客空間。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014385"},{"id":"00014387","register_sub_id":"101","register_pk":"511376","name":"真龍寺山門","kana":"しんりゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"岐阜県","address":"岐阜県岐阜市長良2509-1","lat":35.45465,"lng":136.785325,"geo_status":"db","era":"昭和23年","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"21 - 0297","desc":"浄土真宗寺院の境内南正面に開く山門。切妻造桟瓦葺、二軒繁垂木の薬医門で、袖塀に潜りを設ける。正面蟇股は精緻な龍を彫り、内部に小組格天井を張る。鐘楼棟梁の弟子の作で、地元大工の仕事ぶりを伝え、百々ケ峰を背にして地域の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014387"},{"id":"00014386","register_sub_id":"101","register_pk":"511375","name":"真龍寺鐘楼","kana":"しんりゅうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市長良2509-1","lat":35.4547,"lng":136.785225,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造、瓦葺、面積6.4㎡","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"21 - 0296","desc":"百々ヶ峰を背に山門と並ぶ浄土真宗寺院の鐘楼。入母屋造桟瓦葺、二軒、三斗組、格天井を張る。乱石積基壇に、内転びの礎盤付円柱を貫・虹梁・頭貫で固めた方一間吹放ちとする。本堂棟梁の弟子の作で、地元大工の仕事ぶりを伝え、歴史的な伽藍景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014386"},{"id":"00014384","register_sub_id":"101","register_pk":"511373","name":"真龍寺本堂","kana":"しんりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市長良2509-1","lat":35.45493889,"lng":136.78534722,"geo_status":"db","era":"明治14年頃／大正9年・令和2年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積263㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"21 - 0294","desc":"百々ヶ峰を背に境内を構える浄土真宗寺院の本堂。入母屋造桟瓦葺、向拝を構え正面７間で規模大きく、平面は内外陣間に矢来内、内陣左右に余間を配す等、真宗本堂の典型。長大な虹梁で柱を省略して外陣を大空間とし、小組格天井、金箔押し彫刻欄間で荘厳する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014384"},{"id":"00005613","register_sub_id":"101","register_pk":"106601","name":"貞照寺稲荷堂","kana":"ていしょうじいなりどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.40728966,"lng":136.95891335,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0100","desc":"宝物館西隣にほぼ東面して建つ。東西棟の切妻造，銅板葺，妻入で，軒は一軒とする。平面は縦長で，前を板敷として奥に棚を設け，正面と両側面に切目縁を設ける。真壁造で，角柱を貫，長押で固めて舟肘木を載せ，正面妻飾に蟇股をつける。簡素だがつくりは丁寧。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005613"},{"id":"00005608","register_sub_id":"101","register_pk":"106596","name":"貞照寺庫裏","kana":"ていしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.407597,"lng":136.959656,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積218㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0095","desc":"本堂の北東，池の東に建つ。東西棟の入母屋造で，南面に唐破風造の玄関を突出し，桟瓦葺とする。内部は玄関奥に応接間，この西に１６畳の大広間や８畳の床の間，東に板間と土間を配する。良材を用い，凝った欄間など，つくりも上質で，当時の和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005608"},{"id":"00005609","register_sub_id":"101","register_pk":"106597","name":"貞照寺書院","kana":"ていしょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.40771528,"lng":136.95967664,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0096","desc":"南北棟の寄棟造，桟瓦葺で，南は庫裏北側に接続している。平面は北を床・棚付の８畳，南を６畳とし，西に縁を設け，室境の小壁に障子，側廻り小壁にガラス戸を入れて開放的にする。皮付桜材の床柱，棚上の網代天井など，要所に数寄屋風意匠を盛り込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005609"},{"id":"00005614","register_sub_id":"101","register_pk":"106602","name":"貞照寺浄水舎","kana":"ていしょうじじょうすいしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.407162,"lng":136.960098,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、面積5.0㎡","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0101","desc":"門の南東に位置する。横長平面の吹放し形式で，屋根は東西棟の切妻造，桟瓦葺，軒は一軒とする。四隅に内転びの角柱を立てて内法貫で固め，舟肘木を載せて桁を受ける。妻飾は蟇股で絵様肘木を載せて棟木を受ける。小規模であるが，境内構成上，欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005614"},{"id":"00005612","register_sub_id":"101","register_pk":"106600","name":"貞照寺宝物庫","kana":"ていしょうじほうもつこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.40706357,"lng":136.95916834,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積125㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0099","desc":"本堂南に北面して建つ。鉄筋コンクリート造，高床式の平屋建で，切妻造屋根を架ける。四周に庇を廻した側廻りは，下部を校倉風とし，上部は角柱を現して縦格子窓，連子窓を設ける。内部１室でガラス天井とする。近代の材料や技術で伝統様式を再構成した事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005612"},{"id":"00005607","register_sub_id":"101","register_pk":"106595","name":"貞照寺本堂","kana":"ていしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.40742958,"lng":136.95915839,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0094","desc":"桁行，梁間とも中央間が広い方５間堂。屋根は入母屋造，正面千鳥破風付，向拝軒唐破風付，瓦棒銅板葺である。軸部から軒廻りまで正統的なつくりで，側面・背面は霊験記の彫物で飾る。鉄筋コンクリート造舞台付の高床上にあり，際だった堂姿を見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005607"}];
